
import importlib.abc, importlib.util, json, os, shutil, sys
_SRC = {'app': ('', True), 'app.analyst': ('"""Titan AI Analyst (livello deterministico): fonde i motori attivi, calcola livelli e filtra.\nL\'LLM potrà solo RACCONTARE questi numeri, mai produrli."""\nfrom __future__ import annotations\nimport math\nfrom dataclasses import dataclass, asdict, field\nimport pandas as pd\nfrom .engines import technical, quant, risk\n\nMODEL_VERSION = f"analyst-1.0.0|{technical.MODEL_VERSION}|{quant.MODEL_VERSION}|{risk.MODEL_VERSION}"\nENGINE_W = {\n    "prudente":   {"technical": .30, "quant": .25, "risk": .45},\n    "bilanciata": {"technical": .35, "quant": .30, "risk": .35},\n    "aggressiva": {"technical": .40, "quant": .40, "risk": .20},\n}\nHORIZON_DAYS = {"1-3m": 63, "3-12m": 189}   # orizzonti >1 anno: richiedono motori fondamentale/macro\nINACTIVE = ["fundamentals", "macro", "news"]\nETF_META = ["ter", "replication", "tracking_difference", "aum", "distribution"]\n\n\n@dataclass\nclass Opportunity:\n    ticker: str; exchange: str; isin: str | None; name: str; asset_class: str; currency: str | None\n    strategy: str; horizon: str; as_of: str\n    score: float; engine_scores: dict; factors: dict\n    entry: float; invalidation: float; target_prudent: float; target_optimistic: float\n    potential_pct: float; potential_loss_pct: float; rr_prudent: float; rr_optimistic: float\n    rationale: str; risks: list; missing: list; data_quality: str; model_version: str\n    benchmark: dict | None = None\n    scenarios: dict = field(default_factory=dict)\n\n    def to_dict(self) -> dict:\n        return asdict(self)\n\n\ndef levels(df: pd.DataFrame, vol: float, horizon: str) -> dict:\n    """Zone di prezzo scalate sulla volatilità dell\'orizzonte (NON sono previsioni)."""\n    last = float(df["close"].iloc[-1])\n    sigma = vol * math.sqrt(HORIZON_DAYS[horizon] / 252) * last\n    support = float(df["low"].iloc[-60:].min())\n    inval = max(support, last - 0.6 * sigma)\n    if inval >= last:\n        inval = last - 0.6 * sigma\n    risk_amt = max(last - inval, 0.25 * sigma)\n    return {\n        "entry": last, "invalidation": inval,\n        "target_prudent": last + 0.5 * sigma, "target_optimistic": last + sigma,\n        "rr_prudent": 0.5 * sigma / risk_amt, "rr_optimistic": sigma / risk_amt,\n        "bear_target": last - sigma,\n    }\n\n\ndef evaluate(inst: dict, df: pd.DataFrame, bench: pd.Series | None, strategy: str, horizon: str,\n             min_score: float = 65.0, min_rr: float = 1.5) -> tuple[Opportunity | None, str]:\n    if horizon not in HORIZON_DAYS:\n        raise NotImplementedError(f"orizzonte {horizon} non ancora supportato: servono i motori fondamentale e macro")\n    t = technical.analyze(df, bench, strategy)  # type: ignore[arg-type]\n    q = quant.analyze(df, strategy)             # type: ignore[arg-type]\n    r = risk.analyze(df, bench, strategy)       # type: ignore[arg-type]\n    eng = {"technical": t, "quant": q, "risk": r}\n    lacking = [k for k, v in eng.items() if v.score is None]\n    if lacking:\n        return None, "dati insufficienti per i motori: " + ", ".join(lacking)\n    if r.extra["excessive"]:\n        return None, "rischio eccessivo: " + "; ".join(r.extra["flags"])\n    w = ENGINE_W[strategy]\n    score = round(sum(w[k] * eng[k].score for k in w), 2)\n    if score < min_score:\n        return None, f"punteggio {score} sotto soglia {min_score}"\n    lv = levels(df, r.extra["vol"], horizon)\n    if lv["rr_optimistic"] < min_rr:\n        return None, f"rapporto rischio/rendimento {lv[\'rr_optimistic\']:.2f} sotto soglia {min_rr}"\n\n    contrib = sorted(((k, f.name, f.score, w[k] * f.weight * f.score, f.note)\n                      for k, e in eng.items() for f in e.factors if f.score is not None),\n                     key=lambda x: -x[3])[:3]\n    rationale = " | ".join(f"Titan {k.capitalize()}: {n} {s:.0f}/100 ({note})" for k, n, s, _, note in contrib)\n    missing = [f"{k}: motore non ancora attivo" for k in INACTIVE]\n    for k, e in eng.items():\n        missing += [f"{k}.{m}" for m in e.missing]\n    meta = inst.get("meta") or {}\n    if inst.get("asset_class") == "etf":\n        missing += [f"etf.{m}" for m in ETF_META if m not in meta]\n    risks = list(r.extra["flags"]) + [\n        "Valutazione parziale: analisi fondamentale, macro e news non ancora integrate",\n        f"Scenario ribassista: area {lv[\'bear_target\']:.2f} (-1σ dell\'orizzonte)",\n        "Le previsioni non sono garantite: possibile perdita del capitale"]\n    if inst.get("asset_class") == "etf" and "ter" not in meta:\n        risks.append("Costi (TER), replica e tracking difference non verificati")\n    last = lv["entry"]\n    opp = Opportunity(\n        ticker=inst["ticker"], exchange=inst["exchange"], isin=inst.get("isin"), name=inst.get("name", inst["ticker"]),\n        asset_class=inst.get("asset_class", "stock"), currency=inst.get("currency"), strategy=strategy, horizon=horizon,\n        as_of=df.index[-1].date().isoformat(), score=score,\n        engine_scores={k: v.score for k, v in eng.items()},\n        factors={k: [asdict(f) for f in e.factors] for k, e in eng.items()},\n        entry=round(last, 4), invalidation=round(lv["invalidation"], 4),\n        target_prudent=round(lv["target_prudent"], 4), target_optimistic=round(lv["target_optimistic"], 4),\n        potential_pct=round((lv["target_optimistic"] / last - 1) * 100, 2),\n        potential_loss_pct=round((lv["invalidation"] / last - 1) * 100, 2),\n        rr_prudent=round(lv["rr_prudent"], 2), rr_optimistic=round(lv["rr_optimistic"], 2),\n        rationale=rationale, risks=risks, missing=missing, data_quality="estimated", model_version=MODEL_VERSION,\n        benchmark=inst.get("benchmark"),\n        scenarios={"rialzista": {"target": round(lv["target_optimistic"], 4)},\n                   "neutrale": {"target": round(last, 4)},\n                   "ribassista": {"target": round(lv["bear_target"], 4)},\n                   "probabilita": None})  # nessuna probabilità finché non c\'è un modello validato\n    return opp, "ok"\n', False), 'app.api_payloads': ('"""Costruzione payload per il frontend (funzioni pure, testabili senza FastAPI)."""\nfrom __future__ import annotations\nimport pandas as pd\nfrom .engines import indicators as ind, technical, quant, risk, analyst\n\n\ndef chart_payload(df: pd.DataFrame, bars: int = 500) -> dict:\n    c = df["close"]\n    d = df.iloc[-bars:]\n    def line(s):\n        s = s.reindex(d.index).dropna()\n        return [{"time": i.strftime("%Y-%m-%d"), "value": round(float(v), 4)} for i, v in s.items()]\n    return {\n        "candles": [{"time": i.strftime("%Y-%m-%d"), "open": round(float(r.open), 4), "high": round(float(r.high), 4),\n                     "low": round(float(r.low), 4), "close": round(float(r.close), 4)} for i, r in d.iterrows()],\n        "sma20": line(ind.sma(c, 20)), "sma50": line(ind.sma(c, 50)), "sma200": line(ind.sma(c, 200)),\n        "price_type": "end-of-day (adjusted)", "last_date": df.index[-1].strftime("%Y-%m-%d"),\n    }\n\n\ndef instrument_payload(df: pd.DataFrame, bench: pd.Series | None, strategy: str, asset_class: str = "etf") -> dict:\n    t, q, r = technical.analyze(df, bench, strategy), quant.analyze(df["close"], bench, strategy), risk.analyze(df, strategy)\n    comp = analyst.combine_engines([t, q, r], asset_class)\n    return {"strategy": strategy, "composite": comp, "technical": t.to_dict(), "quant": q.to_dict(), "risk": r.to_dict(),\n            "chart": chart_payload(df)}\n', False), 'app.enrich': ('"""Arricchimenti per la lettura da principianti: classificazione (dedotta, dichiarata come tale), volumi giornalieri/mensili, storico.\nSettore e area sono DEDOTTI da nome, indice e classe Borsa Italiana: la composizione reale per Paese/settore richiede i dati dell\'emittente."""\nfrom __future__ import annotations\nimport numpy as np\nimport pandas as pd\n\nCONT = [  # (parole chiave in MAIUSCOLO, continente/area)\n    (("EMERGING", "EMERGENTI", " EM "), "Mercati emergenti"), (("WORLD", "GLOBAL", "ACWI", "ALL-WORLD", "ALL WORLD"), "Mondo"),\n    (("EUROP", "STOXX", "EURO ", "EMU", "DAX", "FTSE MIB", "CAC", "EUROZONA"), "Europa"),\n    (("USA", " US ", "S&P", "NASDAQ", "NORTH AMERICA", "RUSSELL", "DOW JONES", "UNITED STATES"), "Nord America"),\n    (("ASIA", "PACIFIC", "JAPAN", "NIKKEI", "TOPIX", "CHINA", "INDIA", "KOREA", "TAIWAN"), "Asia-Pacifico"),\n    (("LATIN", "BRAZIL", "BRASIL"), "America Latina"), (("AFRICA",), "Africa"),\n]\nCOUNTRY = [(("S&P 500", "NASDAQ", "RUSSELL", "DOW JONES", "USA", "UNITED STATES"), "Stati Uniti"), (("JAPAN", "NIKKEI", "TOPIX"), "Giappone"),\n           (("CHINA",), "Cina"), (("INDIA",), "India"), (("DAX", "GERMAN"), "Germania"), (("CAC", "FRANCE"), "Francia"),\n           (("FTSE MIB", "ITALY", "ITALIA", "BTP"), "Italia"), (("FTSE 100", "UNITED KINGDOM", " UK "), "Regno Unito"),\n           (("SWISS", "SMI"), "Svizzera"), (("KOREA",), "Corea del Sud"), (("BRAZIL", "BRASIL"), "Brasile")]\nSECTOR = [(("SEMICONDUCT",), "Semiconduttori"), (("ARTIFICIAL", " AI ", "ROBOT"), "Intelligenza artificiale"),\n          (("TECH", "SOFTWARE", "CLOUD", "CYBER", "INFORMATION TECHNOLOGY", "NASDAQ"), "Tecnologia"),\n          (("ENERGY", "OIL", "GAS", "ENERGIA"), "Energia"), (("HEALTH", "PHARMA", "BIOTECH", "SALUTE"), "Salute"),\n          (("FINANCIAL", "BANK", "INSURANCE", "FINANZ"), "Finanza"), (("REAL ESTATE", "REIT", "PROPERTY"), "Immobiliare"),\n          (("CONSUMER", "CONSUMI", "LUXURY"), "Consumi"), (("INDUSTRIAL",), "Industria"), (("UTILIT",), "Servizi di pubblica utilità"),\n          (("MATERIAL", "MINING", "METALS"), "Materiali"), (("GOLD", "PRECIOUS", "SILVER", " ORO"), "Oro e metalli preziosi"),\n          (("COMMODIT", "RAW MATERIAL", "AGRICULT"), "Materie prime"), (("CLEAN", "WATER", "RENEWABLE", "ENVIRONMENT", "CLIMATE", "ESG"), "Ambiente e rinnovabili")]\n\n\ndef _hit(text: str, table):\n    for keys, label in table:\n        if any(k in text for k in keys):\n            return label\n    return None\n\n\ndef classify(name: str, benchmark: str | None, bi_class: str | None, bi_area: str | None, asset_class: str = "etf", sector_hint: str | None = None) -> dict:\n    txt = f" {name} {benchmark or \'\'} {bi_area or \'\'} ".upper()\n    cls = (bi_class or "").upper()\n    if asset_class == "stock":\n        kind = "Azione"\n    elif "OBBLIG" in cls or "BOND" in txt or "TREASURY" in txt or "GOVERNMENT" in txt or "CORPORATE" in txt:\n        kind = "Obbligazionario"\n    elif "MONET" in cls or "MONEY MARKET" in txt or "OVERNIGHT" in txt:\n        kind = "Monetario"\n    elif "COMMOD" in cls or "MATERIE" in cls or _hit(txt, [(("GOLD", "COMMODIT", "SILVER", "PRECIOUS"), 1)]):\n        kind = "Materie prime"\n    elif "AZION" in cls or "EQUITY" in txt or True:\n        kind = "Azionario"\n    continent = _hit(txt, CONT) or "n/d"\n    country = _hit(txt, COUNTRY)\n    sector = sector_hint or _hit(txt, SECTOR)\n    if not sector:\n        sector = "Diversificato (tutti i settori)" if kind == "Azionario" and continent != "n/d" else "n/d"\n    return {"tipo": kind, "continente": continent, "paese": country, "settore": sector,\n            "nota": "classificazione dedotta da nome, indice e classe di Borsa Italiana; composizione reale per Paese/settore non disponibile"}\n\n\ndef volume_stats(df: pd.DataFrame) -> dict:\n    """Scambi stimati da prezzi e volumi giornalieri (Yahoo): ultima seduta, media 20 sedute, somma ultimo mese (21 sedute)."""\n    t = (df["close"] * df["volume"]).replace(0, np.nan).dropna()\n    if len(t) < 21:\n        return {}\n    return {"last_session": float(t.iloc[-1]), "avg_20d": float(t.iloc[-20:].mean()), "month_21d": float(t.iloc[-21:].sum()),\n            "month_shares": float(df["volume"].iloc[-21:].sum())}\n\n\ndef hist_range(close: pd.Series, days: int = 126) -> dict | None:\n    if len(close) < days + 250:\n        return None\n    r = (close.shift(-days) / close - 1).dropna() * 100\n    p10, p50, p90 = np.percentile(r, [10, 50, 90])\n    return {"giorni": days, "p10": round(float(p10), 1), "p50": round(float(p50), 1), "p90": round(float(p90), 1), "campioni": int(len(r))}\n', False), 'app.explain': ('"""Spiegazioni per principianti generate da REGOLE sui punteggi calcolati (nessun testo inventato): perché oggi, cosa tenere d\'occhio, stima."""\nfrom __future__ import annotations\nfrom .enrich import classify, hist_range, volume_stats\n\nLEVEL = lambda s: "basso" if s >= 70 else ("medio" if s >= 45 else "alto")\n\n\ndef _f(ev, key):\n    out = {}\n    for name in ("technical", "etf", "fundamentals"):\n        e = ev.get(name)\n        if e:\n            for fa in e.factors:\n                if fa.score is not None:\n                    out.setdefault(fa.name, (fa.score, fa.weight, fa.value))\n    return out\n\n\ndef build(inst, ev: dict, etf_rec, df, strategy: str) -> dict:\n    f = _f(ev, None)\n    why, watch = [], []\n    g = lambda n: f.get(n, (None, 0, None))\n    cand = []  # (priorità, testo)\n    if g("trend")[0] is not None:\n        s = g("trend")[0]\n        cand.append((s * .30, "Il prezzo è in tendenza rialzista: si trova sopra le medie a 50 e 200 giorni." if s >= 80 else\n                     "Il trend è positivo ma non ancora consolidato." if s >= 60 else None))\n    s = g("momentum")[0]\n    if s is not None: cand.append((s * .20, "Ha ancora slancio: il movimento recente è forte senza essere eccessivo." if s >= 70 else None))\n    s = g("rel_strength")[0]\n    if s is not None: cand.append((s * .20, "Negli ultimi 3 mesi ha fatto meglio del mercato di riferimento." if s >= 65 else None))\n    s = g("risk")[0]\n    if s is not None: cand.append((s * .15, "Oscilla poco: il prezzo è relativamente stabile." if s >= 70 else None))\n    s, _, v = g("costo_ter")\n    if s is not None and s >= 75: cand.append((s * .25, f"Costi bassi: {v:.2f}% all\'anno."))\n    s = g("tracking_difference")[0]\n    if s is not None and s >= 80: cand.append((s * .15, "Segue molto fedelmente il suo indice di riferimento."))\n    s = g("dimensione")[0]\n    if s is not None and s >= 70: cand.append((s * .10, "È un fondo di grandi dimensioni."))\n    s = g("liquidita")[0]\n    if s is not None and s >= 70: cand.append((s * .15, "Si scambia molto: è facile comprare e vendere."))\n    for n, txt in (("crescita_ricavi", "L\'azienda sta facendo crescere i ricavi."), ("redditivita", "È molto redditizia."),\n                   ("solidita", "Ha un debito contenuto rispetto a quanto guadagna."), ("flussi_cassa", "Genera cassa in modo solido."),\n                   ("valutazione", "Il prezzo è ragionevole rispetto agli utili.")):\n        s = g(n)[0]\n        if s is not None and s >= 70: cand.append((s * .2, txt))\n    why = [t for _, t in sorted(((p, t) for p, t in cand if t), reverse=True)][:4]\n    if not why: why = ["Nessun punto di forza netto: è tra i migliori solo in termini relativi."]\n    # cosa tenere d\'occhio\n    s = g("posizione_52w")[0]\n    if s is not None and s >= 90: watch.append("Il prezzo è vicino al massimo degli ultimi 12 mesi: dopo una salita lunga può fermarsi o ritracciare.")\n    s = g("momentum")[0]\n    if s is not None and s < 45: watch.append("La spinta recente si sta indebolendo.")\n    watch += list(ev["risk"].extra.get("flags", []))\n    if ev.get("etf"): watch += ev["etf"].extra.get("flags", [])\n    miss = ev["composite"].get("missing", [])\n    if miss: watch.append("Non ancora considerati: " + ", ".join(m.replace("titan_", "") for m in miss) + ".")\n    watch.append("È una stima, non una garanzia: il prezzo può anche scendere.")\n    rscore = ev["risk"].score if ev["risk"].score is not None else 50\n    rec = etf_rec\n    cl = classify(inst.name, getattr(rec, "benchmark", None), getattr(rec, "bi_class", None), getattr(rec, "bi_area", None), inst.asset_class, getattr(inst, "sector", None))\n    vs = volume_stats(df)\n    facts = {**cl, "ter_pct": getattr(rec, "ter_pct", None), "aum": getattr(rec, "aum", None), "aum_ccy": getattr(rec, "aum_ccy", None),\n             "fund_ccy": getattr(rec, "fund_ccy", None), "trade_ccy": inst.currency, "distribution": getattr(rec, "distribution", None),\n             "issuer": getattr(rec, "issuer", None), "benchmark": getattr(rec, "benchmark", None),\n             "vol_day": getattr(rec, "turnover", None) or vs.get("last_session"), "vol_day_src": "Borsa Italiana" if getattr(rec, "turnover", None) else "stima Yahoo",\n             "vol_avg20": vs.get("avg_20d"), "vol_month": (rec.turnover_month_m * 1e6 if getattr(rec, "turnover_month_m", None) else vs.get("month_21d")), "spread_pct": getattr(rec, "spread_pct", None), "perf_1m": getattr(rec, "perf_1m", None),\n             "perf_6m": getattr(rec, "perf_6m", None), "perf_ytd": getattr(rec, "perf_ytd", None)}\n    return {"why": why, "watch": watch, "risk_level": LEVEL(rscore), "facts": facts, "hist": hist_range(df["close"])}\n\n\ndef etf_text(rec: dict, factors: list, flags: list) -> tuple[list, list]:\n    """Perché / cosa tenere d\'occhio per un ETF valutato solo con i dati della scheda (senza storico prezzi)."""\n    f = {n: sc for n, sc, *_ in factors if sc is not None}\n    why = []\n    if f.get("costo_ter", 0) >= 75 and rec.get("ter_pct") is not None: why.append(f"Costi bassi: {rec[\'ter_pct\']:.2f}% all\'anno.".replace(".", ",", 1) if False else f"Costi bassi: {str(round(rec[\'ter_pct\'], 2)).replace(\'.\', \',\')}% all\'anno.")\n    if f.get("tracking_difference", 0) >= 80: why.append("Segue molto fedelmente il suo indice di riferimento.")\n    if f.get("dimensione", 0) >= 70: why.append("È un fondo di grandi dimensioni.")\n    if f.get("liquidita", 0) >= 70: why.append("Si scambia molto: è facile comprare e vendere.")\n    if f.get("spread", 0) >= 80 and rec.get("spread_pct") is not None: why.append(f"Costo di negoziazione molto basso: spread {str(round(rec[\'spread_pct\'], 3)).replace(\'.\', \',\')}%.")\n    if f.get("momentum_6m", 0) >= 60 and rec.get("perf_6m") is not None: why.append(f"Negli ultimi 6 mesi è salito del {str(round(rec[\'perf_6m\'], 1)).replace(\'.\', \',\')}%.")\n    watch = list(flags)\n    if f.get("posizione_52w", 0) >= 85: watch.append("Il prezzo è vicino al massimo degli ultimi 12 mesi: dopo una salita lunga può fermarsi o ritracciare.")\n    watch.append("Senza lo storico dei prezzi non è possibile stimare livelli e potenziale di crescita.")\n    watch.append("È una stima, non una garanzia: il prezzo può anche scendere.")\n    return why or ["Nessun punto di forza netto sui dati disponibili."], watch\n', False), 'app.export_artifact': ('"""Esporta il Radar in formato compatto per la pagina web (artefatto Claude): picks + esclusi + ultimi 250 prezzi dei soli strumenti selezionati."""\nfrom __future__ import annotations\nfrom datetime import datetime, timezone\nfrom .enrich import classify\nfrom .explain import etf_text\n\n\ndef compact(res: dict, prices: dict, source: str, provider: str, max_per_strategy: int = 40, etf_view: list | None = None) -> dict:\n    picks, px = [], {}\n    for s, lst in res["picks"].items():\n        for p in lst[:max_per_strategy]:\n            d = p["score_detail"]\n            picks.append({"n": p["name"], "t": p["ticker"], "i": p["isin"], "x": p["exchange"], "c": p["asset_class"], "s": s,\n                          "sc": round(p["score"]), "px": p["price"], "d": p["price_date"], "e": p["entry_indicative"], "iv": p["invalidation"],\n                          "tp": p["target_prudent"], "to": p["target_optimistic"], "up": p["upside_prudent_pct"], "uo": p["upside_optimistic_pct"],\n                          "ls": p["potential_loss_pct"], "rr": p["risk_reward_prudent"], "h": p["horizon"], "fl": p["risk_flags"],\n                          "en": [[e["engine"].replace("titan_", ""), round(e["score"]), e["weight"]] for e in d["engines"]],\n                          "ms": [m.replace("titan_", "") for m in d["missing_engines"]], "q": d["data_quality"],\n                          "f": [[f["name"].replace("_", " "), round(f["score"]), f["weight"]]\n                                for f in (d.get("technical_factors") or d.get("bond_factors") or []) if f["score"] is not None],\n                          "pt": p.get("potential"), "why": p.get("why", []), "wa": p.get("watch", []), "rl": p.get("risk_level"), "fx": p.get("facts"), "hi": p.get("hist"),\n                          "by": None if p["asset_class"] != "bond" else [round(d["ytm"] * 100, 2), round(d["net_ytm_est"] * 100, 2), round(d["mod_duration"], 1)]})\n            if p["asset_class"] != "bond" and p["ticker"] in prices and p["ticker"] not in px:\n                px[p["ticker"]] = [round(float(v), 2) for v in prices[p["ticker"]]["close"].iloc[-250:]]\n    etf = [{"r": {k: i["rec"].get(k) for k in ("isin", "ticker", "name", "ter_pct", "fund_ccy", "trade_ccy", "aum", "aum_ccy", "turnover", "perf_1m", "perf_6m", "perf_ytd", "last_price", "last_date", "benchmark", "distribution", "issuer", "bi_class", "bi_area", "turnover_month_m", "spread_pct")},\n            "sc": {k: v["score"] for k, v in i["scores"].items()}, "fl": i["scores"]["bilanciata"]["flags"],\n            "fa": i["scores"]["bilanciata"]["factors"], "nt": i["rec"].get("notes", []),\n            "wy": etf_text(i["rec"], i["scores"]["bilanciata"]["factors"], i["scores"]["bilanciata"]["flags"])[0], "wt": etf_text(i["rec"], i["scores"]["bilanciata"]["factors"], i["scores"]["bilanciata"]["flags"])[1],\n            "cl": classify(i["rec"].get("name") or "", i["rec"].get("benchmark"), i["rec"].get("bi_class"), i["rec"].get("bi_area"))} for i in (etf_view or [])]\n    return {"v": 2, "an": res.get("analyzed", [])[:300], "etf": etf, "date": res["date"], "picks": picks, "px": px, "demo": bool(res.get("demo")), "source": source, "provider": provider,\n            "generated": datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M UTC"),\n            "ex": [[e["ticker"], e.get("strategy", ""), e["reason"]] for e in res["excluded"]][:300]}\n', False), 'app.service': ('"""Servizio automatico quotidiano: ETF (Borsa Italiana + Yahoo), azioni (indici da fonti pubbliche + Yahoo), obbligazioni MOT (Borsa Italiana).\nOgni sezione è isolata: se una fonte fallisce le altre proseguono e /v1/status (o status.json) spiega cosa è andato storto."""\nfrom __future__ import annotations\nimport json, os, threading, time\nfrom concurrent.futures import ThreadPoolExecutor\nfrom datetime import date, datetime, timedelta\nfrom zoneinfo import ZoneInfo\nfrom .engines import etf as etfmod\nfrom .export_artifact import compact\nfrom .pipeline.radar import Instrument, build_radar\nfrom .pipeline.repository import content_hash\nfrom .universe import bi_bonds, bi_stats, discovery, stocks\nfrom .universe.borsa_italiana import URL, parse, to_text, _get as bi_get_default\nfrom .universe.etf_verifier import Verification\n\nTZ = ZoneInfo("Europe/Rome")\nSTORE = os.environ.get("STORE_DIR", "data/store")\nTHROTTLE = 1.0          # pausa tra richieste a Borsa Italiana (per non ricevere 429)\nSCRAPE_WORKERS = 2\nTHROTTLE_BI = 0.7\nRUN_AFTER = (18, 15)   # ETFplus e MOT chiudono alle 17:35\nLOCK = threading.Lock()\nEXCH = {".MI": "XMIL", ".DE": "XETR", ".PA": "XPAR", ".L": "XLON"}\n\n\ndef _w(name: str, obj) -> None:\n    os.makedirs(STORE, exist_ok=True)\n    tmp = f"{STORE}/{name}.tmp"\n    json.dump(obj, open(tmp, "w", encoding="utf-8"), ensure_ascii=False, default=str)\n    os.replace(tmp, f"{STORE}/{name}")\n\n\ndef read(name: str, default=None):\n    try:\n        return json.load(open(f"{STORE}/{name}", encoding="utf-8"))\n    except (FileNotFoundError, json.JSONDecodeError):\n        return default\n\n\nclass Polite:\n    """Limita il ritmo delle richieste (condiviso fra i thread) e riprova con attesa crescente su 429/5xx."""\n    def __init__(self, get, min_interval: float = 0.7, tries: int = 5, sleep=time.sleep):\n        self.get, self.min_interval, self.tries, self.sleep = get, min_interval, tries, sleep\n        self.lock, self.last, self.retries_429 = threading.Lock(), 0.0, 0\n\n    def __call__(self, url):\n        st, body = 0, ""\n        for attempt in range(self.tries):\n            with self.lock:\n                wait = self.min_interval - (time.monotonic() - self.last)\n                if wait > 0: self.sleep(wait)\n                self.last = time.monotonic()\n            st, body = self.get(url)\n            if st in (429, 500, 502, 503, 504):\n                self.retries_429 += 1\n                self.sleep(min(60, 3 * 2 ** attempt)); continue\n            return st, body\n        return st, body\n\n\nclass Prechecked:\n    def __init__(self, ok: set): self.ok = ok\n    def verify(self, isin, ticker, ccy=""):\n        return Verification(isin in self.ok, "verificato sul sito di Borsa Italiana" if isin in self.ok else "non verificato")\n\n\ndef last_trading_day(now: datetime) -> date:\n    d = now.date()\n    if now.weekday() >= 5 or (now.hour, now.minute) < RUN_AFTER:\n        d -= timedelta(days=1)\n    while d.weekday() >= 5:\n        d -= timedelta(days=1)\n    return d\n\n\ndef is_stale(now: datetime | None = None) -> bool:\n    now = now or datetime.now(TZ)\n    ok = (read("status.json") or {}).get("last_success_date")\n    return ok is None or date.fromisoformat(ok) < last_trading_day(now)\n\n\ndef _pmap(fn, items, workers):\n    with ThreadPoolExecutor(workers) as ex:\n        return list(ex.map(fn, items))\n\n\ndef refresh(provider, bi_get=bi_get_default, get_bytes=bi_stats._get_bytes, top_n: int | None = None, benchmark: str | None = None, workers: int | None = None,\n            now: datetime | None = None, max_stocks: int | None = None, top_bonds: int = 60) -> dict:\n    if not LOCK.acquire(blocking=False):\n        return {"state": "già in esecuzione"}\n    now = now or datetime.now(TZ)\n    today = now.date()\n    workers = workers or SCRAPE_WORKERS\n    top_n = top_n or int(os.environ.get("TOP_N_ETF", "150"))\n    max_stocks = max_stocks or int(os.environ.get("MAX_STOCKS", "900"))\n    benchmark = benchmark or os.environ.get("BENCHMARK", "SWDA.MI")\n    st = {"state": "in corso", "started": now.isoformat(timespec="seconds"), "step": "avvio", "errors": [], "sections": {},\n          "last_success_date": (read("status.json") or {}).get("last_success_date")}\n    _w("status.json", st)\n    prices, uni, byisin, snaps, recs = {}, [], {}, {}, []\n    raw_get = bi_get\n    bi_get = Polite(raw_get, min_interval=THROTTLE_BI)          # rispetta i limiti di Borsa Italiana (errori 429)\n\n    def step(name):\n        st["step"] = name; _w("status.json", st)\n\n    try:\n        # ---------- ETF ----------\n        sec = st["sections"]["etf"] = {}\n        try:\n            step("ETF: elenco ufficiale Borsa Italiana (statistiche mensili)")\n            rows, sdiag = bi_stats.latest(get_bytes, today)\n            sec["statistiche"] = sdiag\n            stat = {r.isin: r for r in rows if r.segment in ("ETF", "ETFA")}\n            sec["escluse_strutturate"] = sum(1 for r in rows if r.segment == "ETFS")\n            if stat:\n                isins = [r.isin for r in sorted(stat.values(), key=lambda r: r.turnover_month_m or 0, reverse=True)][:top_n]\n            else:\n                isins, diag = discovery.discover(bi_get); sec["discovery"] = diag\n            sec.update(universe_found=len(isins), stats_rows=len(rows), rejected={})\n            step("ETF: schede di Borsa Italiana")\n\n            def check(isin):\n                time.sleep(THROTTLE); s_, b_ = bi_get(URL.format(isin=isin)); return isin, s_, b_\n            ok, recs_all = set(), {}\n            for isin, s_, body in _pmap(check, isins, workers):\n                r = None\n                if s_ == 200 and isin in body.upper():\n                    r = parse(body, isin)\n                    if (r.mic != "ETFP" or not r.ticker) and "debug_scheda" not in sec:\n                        sec["debug_scheda"] = {"isin": isin, "estratto": to_text(body)[:700], "mic": r.mic, "ticker": r.ticker, "ter": r.ter_pct}\n                else:\n                    k = f"scheda non scaricata (HTTP {s_})"; sec["rejected"][k] = sec["rejected"].get(k, 0) + 1\n                srow = stat.get(isin)\n                if r is None and srow is None:\n                    continue\n                if r is None:\n                    r = etfmod.EtfRecord(isin=isin, ticker=srow.ticker, name=srow.name)\n                r.asof = today.isoformat(); r.sources = r.sources or [URL.format(isin=isin)]\n                if srow:   # l\'elenco ufficiale delle statistiche ETFplus prova la quotazione su Borsa Italiana\n                    r.ticker = r.ticker or srow.ticker; r.name = r.name or srow.name\n                    r.turnover_month_m, r.spread_pct, r.trades_month = srow.turnover_month_m, srow.spread_pct, srow.trades_month\n                    r.mic = r.mic or "ETFP"; r.sources.append(sdiag.get("url", "statistiche ETFplus Borsa Italiana"))\n                if r.mic == "ETFP" and r.ticker:\n                    ok.add(isin); recs_all[isin] = r\n                else:\n                    sec["rejected"]["non risulta ETFplus"] = sec["rejected"].get("non risulta ETFplus", 0) + 1\n            sec["verified"] = len(ok)\n            recs = sorted(recs_all.values(), key=lambda r: (r.turnover_month_m or 0, r.turnover or 0), reverse=True)\n            liquid = [r for r in recs if (r.turnover_month_m or r.turnover or 0) > 0][:top_n]\n            step("ETF: prezzi (Yahoo Finance)")\n\n            def px(r):\n                try: return r.ticker, provider.daily(r.ticker, "XMIL"), None\n                except Exception as e: return r.ticker, None, f"{type(e).__name__}: {e}"  # noqa: BLE001\n            fails = []\n            for t, df, err in _pmap(px, liquid, 4):\n                (prices.__setitem__(t, df) if df is not None else fails.append(f"{t}: {err}"))\n            for r in liquid:\n                c = (getattr(provider, "meta", {}).get(r.ticker) or {}).get("currency")\n                if c: r.trade_ccy = c.upper()\n            byisin = {r.isin: r for r in liquid}\n            uni += [Instrument("etf", r.name or r.ticker, r.ticker, "XMIL", r.trade_ccy or "EUR", r.isin) for r in liquid if r.ticker in prices]\n            sec.update(selected=len(liquid), priced=sum(1 for r in liquid if r.ticker in prices), price_failures=fails[:15])\n        except Exception as e:  # noqa: BLE001\n            sec["errore"] = f"{type(e).__name__}: {e}"; st["errors"].append(f"ETF: {e}")\n        # ---------- OBBLIGAZIONI ----------\n        sec = st["sections"]["bond"] = {}\n        try:\n            step("Obbligazioni: schede MOT di Borsa Italiana")\n            bis, diag = bi_bonds.discover(bi_get)\n            sec.update(universe_found=len(bis), discovery=diag, scartate={})\n\n            def getb(item):\n                isin, section = item\n                time.sleep(THROTTLE); s_, b_ = bi_get(bi_bonds.URL.format(isin=isin, section=section)); return isin, s_, b_\n            quotes = []\n            for isin, s_, body in _pmap(getb, list(bis.items()), workers):\n                if s_ != 200:\n                    k = f"scheda non trovata (HTTP {s_})"; sec["scartate"][k] = sec["scartate"].get(k, 0) + 1; continue\n                q = bi_bonds.parse(body); good, why = bi_bonds.eligible(q, today)\n                if not good:\n                    sec["scartate"][why] = sec["scartate"].get(why, 0) + 1\n                    if "dati della scheda incompleti" == why and "debug_scheda" not in sec:\n                        sec["debug_scheda"] = {"isin": isin, "estratto": to_text(body)[:700], "isin_letto": q.isin, "prezzo": q.price_ref, "scadenza": str(q.maturity), "cedola": q.coupon_pct, "freq": q.freq}\n                    continue\n                quotes.append(q)\n            quotes.sort(key=lambda q: (q.volume or 0), reverse=True)\n            for q in quotes[:top_bonds]:\n                snaps[q.isin] = bi_bonds.to_snapshot(q, today)\n                uni.append(Instrument("bond", q.name, q.name, "XMIL", q.currency, q.isin))\n            sec["selezionate"] = len(snaps)\n        except Exception as e:  # noqa: BLE001\n            sec["errore"] = f"{type(e).__name__}: {e}"; st["errors"].append(f"Obbligazioni: {e}")\n        # ---------- AZIONI ----------\n        sec = st["sections"]["stock"] = {}\n        try:\n            step("Azioni: universo (indici) e prezzi (Yahoo Finance)")\n            refs, diag = stocks.discover(bi_get)\n            sec.update(universe_found=len(refs), sorgenti=diag)\n            refs = refs[:max_stocks]\n\n            def pxs(ref):\n                try: return ref, provider.daily(ref.symbol, None), None\n                except Exception as e: return ref, None, f"{type(e).__name__}: {e}"  # noqa: BLE001\n            fails, n = [], 0\n            for ref, df, err in _pmap(pxs, refs, 4):\n                if df is None:\n                    fails.append(f"{ref.symbol}: {err}"); continue\n                prices[ref.symbol] = df; n += 1\n                suf = next((k for k in EXCH if ref.symbol.endswith(k)), "")\n                c = (getattr(provider, "meta", {}).get(ref.symbol) or {}).get("currency")\n                uni.append(Instrument("stock", ref.name, ref.symbol, EXCH.get(suf, "US"), (c or "USD").upper(), None, None, ref.sector))\n            sec.update(priced=n, price_failures=fails[:15], failures_total=len(fails))\n        except Exception as e:  # noqa: BLE001\n            sec["errore"] = f"{type(e).__name__}: {e}"; st["errors"].append(f"Azioni: {e}")\n        # ---------- CALCOLO ----------\n        step("Calcolo Radar")\n        bench = None\n        try: bench = provider.daily(benchmark)["close"]\n        except Exception as e: st["errors"].append(f"benchmark {benchmark}: {e}")  # noqa: BLE001\n        res = build_radar(uni, lambda i: prices[i.ticker], bench, Prechecked(set(byisin)), today=today,\n                          load_etf=lambda i: byisin[i.isin], load_bond=lambda i: snaps[i.isin])\n        etf_view = [{"rec": etfmod.record_dict(r), "scores": {s: {"score": (a := etfmod.analyze(r, s)).score,\n                     "factors": [[f.name, None if f.score is None else round(f.score), round(f.weight, 3), f.note] for f in a.factors],\n                     "flags": a.extra["flags"], "missing": a.missing} for s in ("prudente", "bilanciata", "aggressiva")}} for r in recs]\n        _w("radar.json", {**res, "generated": now.isoformat(timespec="seconds")})\n        _w("etf.json", {"date": today.isoformat(), "items": etf_view})\n        exp = compact(res, prices, "Borsa Italiana (ETF, obbligazioni), indici pubblici (azioni)", getattr(provider, "code", "?"), etf_view=etf_view)\n        exp["cov"] = {"etf": len(st["sections"].get("etf", {}).get("selected") and etf_view or []), "etf_verificati": st["sections"].get("etf", {}).get("verified"), "azioni": st["sections"].get("stock", {}).get("priced"), "azioni_universo": st["sections"].get("stock", {}).get("universe_found"), "bond": st["sections"].get("bond", {}).get("selezionate"), "bond_universo": st["sections"].get("bond", {}).get("universe_found"), "statistiche": (st["sections"].get("etf", {}).get("statistiche") or {}).get("periodo")}\n        _w("export.json", exp)\n        path = f"{STORE}/predictions.jsonl"\n        seen = {json.loads(l)["hash"] for l in open(path, encoding="utf-8")} if os.path.exists(path) else set()\n        with open(path, "a", encoding="utf-8") as f:   # append-only\n            for s, lst in res["picks"].items():\n                for p in lst:\n                    h = content_hash({**p, "published_on": res["date"]})\n                    if h not in seen: f.write(json.dumps({"hash": h, "published_on": res["date"], "pick": p}, ensure_ascii=False, default=str) + "\\n")\n        st["bi_retries_429"] = getattr(bi_get, "retries_429", 0)\n        any_data = any(st["sections"][k].get("priced") or st["sections"][k].get("selezionate") for k in st["sections"])\n        st.update(state="completato" if any_data else "errore", step="fine", finished=datetime.now(TZ).isoformat(timespec="seconds"),\n                  picks={s: len(v) for s, v in res["picks"].items()}, excluded=len(res["excluded"]))\n        if any_data: st["last_success_date"] = today.isoformat()\n    except Exception as e:  # noqa: BLE001\n        st.update(state="errore", errors=st["errors"] + [f"{type(e).__name__}: {e}"], finished=datetime.now(TZ).isoformat(timespec="seconds"))\n    finally:\n        _w("status.json", st); LOCK.release()\n    return st\n\n\ndef scheduler(provider, interval: int = 300):\n    def loop():\n        while True:\n            try:\n                if is_stale(): refresh(provider)\n            except Exception:  # noqa: BLE001\n                pass\n            time.sleep(interval)\n    t = threading.Thread(target=loop, daemon=True, name="titan-scheduler"); t.start(); return t\n', False), 'app.store': ('"""Archivio previsioni IMMUTABILI (SQLite per sviluppo/test; stesse regole del trigger Postgres)."""\nimport json, sqlite3\n\nDDL = """\ncreate table if not exists prediction(\n  id integer primary key autoincrement,\n  ticker text not null, exchange text not null, isin text, name text, asset_class text,\n  as_of text not null, strategy text not null, horizon text not null,\n  score real not null, entry real not null, invalidation real not null,\n  target_prudent real not null, target_optimistic real not null,\n  bench_ticker text, bench_exchange text,\n  model_version text not null, payload text not null,\n  created_at text not null default (datetime(\'now\')),\n  unique(ticker, exchange, as_of, strategy, horizon, model_version));\ncreate table if not exists prediction_outcome(\n  prediction_id integer not null references prediction(id), days integer not null,\n  measured_on text not null, start_price real, end_price real, total_return real, bench_return real,\n  hit_target integer, invalidated integer, uses_adj_close integer,\n  primary key(prediction_id, days));\ncreate trigger if not exists p_no_upd before update on prediction begin select raise(abort,\'prediction immutabile\'); end;\ncreate trigger if not exists p_no_del before delete on prediction begin select raise(abort,\'prediction immutabile\'); end;\ncreate trigger if not exists o_no_upd before update on prediction_outcome begin select raise(abort,\'outcome immutabile\'); end;\ncreate trigger if not exists o_no_del before delete on prediction_outcome begin select raise(abort,\'outcome immutabile\'); end;\n"""\n\n\nclass PredictionStore:\n    def __init__(self, path: str = "titan.db"):\n        self.db = sqlite3.connect(path)\n        self.db.row_factory = sqlite3.Row\n        self.db.executescript(DDL)\n\n    def save(self, o) -> bool:\n        """Idempotente: rilanciare la scansione dello stesso giorno non duplica né modifica."""\n        b = o.benchmark or {}\n        cur = self.db.execute(\n            "insert or ignore into prediction(ticker,exchange,isin,name,asset_class,as_of,strategy,horizon,score,entry,"\n            "invalidation,target_prudent,target_optimistic,bench_ticker,bench_exchange,model_version,payload) "\n            "values(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",\n            (o.ticker, o.exchange, o.isin, o.name, o.asset_class, o.as_of, o.strategy, o.horizon, o.score, o.entry,\n             o.invalidation, o.target_prudent, o.target_optimistic, b.get("ticker"), b.get("exchange"),\n             o.model_version, json.dumps(o.to_dict())))\n        self.db.commit()\n        return cur.rowcount == 1\n\n    def list(self, as_of: str | None = None, strategy: str | None = None) -> list[dict]:\n        q, a = "select * from prediction where 1=1", []\n        if as_of: q += " and as_of=?"; a.append(as_of)\n        if strategy: q += " and strategy=?"; a.append(strategy)\n        return [dict(r) for r in self.db.execute(q + " order by score desc", a)]\n\n    def has_outcome(self, pid: int, days: int) -> bool:\n        return self.db.execute("select 1 from prediction_outcome where prediction_id=? and days=?", (pid, days)).fetchone() is not None\n\n    def add_outcome(self, **k):\n        cols = ",".join(k)\n        self.db.execute(f"insert or ignore into prediction_outcome({cols}) values({\',\'.join(\'?\' * len(k))})", list(k.values()))\n        self.db.commit()\n\n    def outcomes(self) -> list[dict]:\n        return [dict(r) for r in self.db.execute("select * from prediction_outcome")]\n', False), 'app.core': ('', True), 'app.core.scoring': ('"""Strutture comuni di scoring: ogni punteggio 0-100 è spiegabile."""\nfrom __future__ import annotations\nfrom dataclasses import dataclass, field, asdict\nfrom datetime import date\nfrom typing import Literal\n\nStrategy = Literal["prudente", "bilanciata", "aggressiva"]\nQuality = Literal["verified", "delayed", "estimated", "missing"]\nMIN_FACTORS = 3  # mai un singolo indicatore come unica motivazione\n\n\n@dataclass\nclass Factor:\n    name: str\n    value: float | None      # valore grezzo (es. RSI=62.1)\n    score: float | None      # 0-100, None se non calcolabile\n    weight: float            # peso (effettivo dopo rinormalizzazione)\n    note: str = ""\n\n\n@dataclass\nclass ScoreResult:\n    engine: str\n    score: float | None\n    factors: list[Factor]\n    data_quality: Quality\n    missing: list[str]\n    as_of: date | None\n    model_version: str\n    extra: dict = field(default_factory=dict)\n\n    def to_dict(self) -> dict:\n        d = asdict(self)\n        d["as_of"] = self.as_of.isoformat() if self.as_of else None\n        return d\n\n\ndef combine(factors: list[Factor]) -> tuple[float | None, list[Factor], list[str]]:\n    """Media pesata con rinormalizzazione dei pesi sui fattori disponibili.\n    Restituisce (score, fattori con peso effettivo, fattori mancanti)."""\n    ok = [f for f in factors if f.score is not None]\n    missing = [f.name for f in factors if f.score is None]\n    if len(ok) < MIN_FACTORS:\n        return None, factors, missing\n    tot = sum(f.weight for f in ok)\n    score = sum(f.score * f.weight for f in ok) / tot\n    eff = [Factor(f.name, f.value, f.score, round(f.weight / tot, 4), f.note) if f.score is not None else f\n           for f in factors]\n    return round(score, 2), eff, missing\n', False), 'app.engines': ('', True), 'app.engines.analyst': ('"""Titan AI Analyst (parte quantitativa): combina i motori disponibili. L\'LLM spiega, non calcola."""\nfrom __future__ import annotations\nfrom ..core.scoring import ScoreResult\n\nMODEL_VERSION = "analyst-3.0.0"\nWEIGHTS = {\n    "etf":   {"titan_technical": .30, "titan_quant": .20, "titan_risk": .20, "titan_etf": .30},\n    "stock": {"titan_technical": .30, "titan_quant": .20, "titan_risk": .20, "titan_fundamentals": .30},\n}\nNOT_IMPLEMENTED = ["titan_macro", "titan_news"]  # dichiarati come mancanti in ogni risultato\n\n\ndef combine_engines(results: list[ScoreResult], asset_class: str = "etf") -> dict:\n    w = WEIGHTS["stock" if asset_class == "stock" else "etf"]\n    ok = [r for r in results if r.score is not None and r.engine in w]\n    missing = [e for e in w if e not in {r.engine for r in ok}] + NOT_IMPLEMENTED\n    if len(ok) < 2:\n        return {"score": None, "missing": missing, "breakdown": [], "quality": "missing"}\n    tot = sum(w[r.engine] for r in ok)\n    score = sum(r.score * w[r.engine] for r in ok) / tot\n    order = ["missing", "estimated", "delayed", "verified"]\n    worst = min((r.data_quality for r in ok), key=order.index)\n    return {"score": round(score, 2), "missing": missing, "quality": min(worst, "estimated", key=order.index),\n            "breakdown": [{"engine": r.engine, "score": r.score, "weight": round(w[r.engine] / tot, 3)} for r in ok],\n            "model_version": MODEL_VERSION}\n', False), 'app.engines.bonds': ('"""Titan Bonds: matematica obbligazionaria (YTM, duration, convessità, rendimento netto) + scoring.\nCalcoli deterministici, giorni ACT/365 (approssimazione dichiarata). Cedole a frequenza annua o semestrale."""\nfrom __future__ import annotations\nfrom dataclasses import dataclass\nfrom datetime import date, timedelta\nimport calendar\nfrom ..core.scoring import Factor, ScoreResult, combine, Strategy\n\nMODEL_VERSION = "bonds-1.0.0"\nRATING = {"AAA": 100, "AA+": 95, "AA": 92, "AA-": 88, "A+": 84, "A": 80, "A-": 76, "BBB+": 70, "BBB": 65, "BBB-": 60,\n          "BB+": 48, "BB": 42, "BB-": 36, "B+": 28, "B": 22, "B-": 16, "CCC": 8, "CC": 4, "C": 2, "D": 0}\nMOODY = {"AAA": "AAA", "AA1": "AA+", "AA2": "AA", "AA3": "AA-", "A1": "A+", "A2": "A", "A3": "A-", "BAA1": "BBB+", "BAA2": "BBB",\n         "BAA3": "BBB-", "BA1": "BB+", "BA2": "BB", "BA3": "BB-", "B1": "B+", "B2": "B", "B3": "B-", "CAA": "CCC"}\n# soglie di esclusione per strategia: rating minimo (punteggio), duration massima\nLIMITS = {"prudente": (60, 5.0), "bilanciata": (36, 9.0), "aggressiva": (16, 15.0)}\n# Aliquote INDICATIVE (verificare con fonte fiscale aggiornata): titoli di Stato/sovranazionali vs societari\nTAX = {"govt": 0.125, "corp": 0.26}\n\n\n@dataclass\nclass BondSnapshot:\n    isin: str\n    name: str\n    currency: str\n    coupon_pct: float            # cedola annua nominale in %\n    maturity: date\n    clean_price: float           # prezzo "tel quel" meno rateo, base 100\n    issuer_type: str = "govt"    # govt | corp\n    rating: str | None = None\n    frequency: int = 1           # cedole/anno: 1 o 2\n    settlement: date | None = None\n    price_date: date | None = None\n    ytm_override: float | None = None     # rendimento effettivo lordo letto da Borsa Italiana\n    net_override: float | None = None     # rendimento effettivo netto letto da Borsa Italiana\n    dur_override: float | None = None     # duration modificata letta da Borsa Italiana\n\n\ndef rating_score(r: str | None) -> float | None:\n    if not r:\n        return None\n    k = r.strip().upper().replace(" ", "")\n    return RATING.get(k) if k in RATING else RATING.get(MOODY.get(k, ""), None)\n\n\ndef _add_months(d: date, m: int) -> date:\n    y, mo = divmod(d.year * 12 + d.month - 1 + m, 12)\n    mo += 1\n    return date(y, mo, min(d.day, calendar.monthrange(y, mo)[1]))\n\n\ndef schedule(b: BondSnapshot, settle: date) -> tuple[date, date, list[date]]:\n    step = 12 // b.frequency\n    dates, k = [], 0\n    while True:\n        d = _add_months(b.maturity, -step * k)\n        if d <= settle:\n            prev = d\n            break\n        dates.append(d); k += 1\n    nxt = dates[-1] if dates else b.maturity\n    return prev, nxt, sorted(dates)\n\n\ndef _pv(b: BondSnapshot, y: float, settle: date, dates: list[date]) -> float:\n    cpn = b.coupon_pct / b.frequency\n    tot = 0.0\n    for d in dates:\n        t = (d - settle).days / 365.0\n        tot += (cpn + (100 if d == b.maturity else 0)) / (1 + y) ** t\n    return tot\n\n\ndef metrics(b: BondSnapshot, settle: date | None = None) -> dict:\n    settle = settle or b.settlement or date.today()\n    if b.maturity <= settle:\n        raise ValueError("titolo scaduto")\n    prev, nxt, dates = schedule(b, settle)\n    cpn = b.coupon_pct / b.frequency\n    accrued = cpn * (settle - prev).days / max((nxt - prev).days, 1)\n    dirty = b.clean_price + accrued\n    lo, hi = -0.5, 2.0\n    for _ in range(200):\n        mid = (lo + hi) / 2\n        if _pv(b, mid, settle, dates) > dirty: lo = mid\n        else: hi = mid\n    y = (lo + hi) / 2\n    pvs = [((cpn + (100 if d == b.maturity else 0)) / (1 + y) ** ((d - settle).days / 365.0), (d - settle).days / 365.0) for d in dates]\n    mac = sum(p * t for p, t in pvs) / dirty\n    conv = sum(p * t * (t + 1) for p, t in pvs) / dirty / (1 + y) ** 2\n    tax = TAX.get(b.issuer_type, TAX["corp"])\n    return {"ytm": y, "mod_duration": mac / (1 + y), "convexity": conv, "accrued": accrued, "dirty_price": dirty,\n            "current_yield": b.coupon_pct / b.clean_price, "years_to_maturity": (b.maturity - settle).days / 365.0,\n            "net_ytm_est": y * (1 - tax), "tax_rate_assumed": tax,\n            "net_note": "stima semplificata: YTM x (1 - aliquota); non include commissioni e bollo"}\n\n\ndef price_at_yield(b: BondSnapshot, new_ytm: float, settle: date | None = None) -> float:\n    """Prezzo tel quel ricalcolato a un diverso rendimento (sensibilità ai tassi, non previsione)."""\n    settle = settle or b.settlement or date.today()\n    prev, nxt, dates = schedule(b, settle)\n    cpn = b.coupon_pct / b.frequency\n    accrued = cpn * (settle - prev).days / max((nxt - prev).days, 1)\n    return _pv(b, new_ytm, settle, dates) - accrued\n\n\ndef _clip(x, lo=0.0, hi=100.0):\n    return float(max(lo, min(hi, x)))\n\n\ndef analyze(b: BondSnapshot, strategy: Strategy = "bilanciata", risk_free: float | None = None) -> ScoreResult:\n    m = metrics(b)\n    calc_ytm = m["ytm"]\n    if b.ytm_override is not None: m["ytm"] = b.ytm_override\n    if b.dur_override is not None: m["mod_duration"] = b.dur_override\n    if b.net_override is not None: m["net_ytm_est"] = b.net_override; m["net_note"] = "rendimento netto effettivo di Borsa Italiana"\n    W = {"prudente": (.20, .40, .30, .10), "bilanciata": (.30, .30, .20, .20), "aggressiva": (.45, .15, .10, .30)}[strategy]\n    rs = rating_score(b.rating)\n    f = []\n    if risk_free is not None:\n        sp = m["ytm"] - risk_free\n        f.append(Factor("rendimento", round(m["ytm"], 4), _clip(sp / 0.04 * 100), W[0], f"YTM {m[\'ytm\']:.2%}, spread vs risk-free {sp:+.2%}"))\n    else:\n        f.append(Factor("rendimento", round(m["ytm"], 4), _clip(m["ytm"] / 0.06 * 100), W[0], f"YTM {m[\'ytm\']:.2%} (soglie assolute: risk-free non fornito)"))\n    f.append(Factor("qualita_credito", rs, rs, W[1], f"rating {b.rating or \'n/d\'}"))\n    f.append(Factor("rischio_tassi", round(m["mod_duration"], 2), _clip(100 - m["mod_duration"] / 12 * 100), W[2], f"duration modificata {m[\'mod_duration\']:.2f}"))\n    eff = m["ytm"] / m["mod_duration"] if m["mod_duration"] > 0 else 0\n    f.append(Factor("efficienza_carry", round(eff, 4), _clip(eff / 0.015 * 100), W[3], "rendimento per unità di duration"))\n    score, eff_f, missing = combine(f)\n    min_rs, max_dur = LIMITS[strategy]\n    flags = []\n    if rs is None and strategy != "aggressiva": flags.append("rating non disponibile: rischio emittente non valutabile")\n    if rs is not None and rs < min_rs: flags.append(f"rating {b.rating} sotto la soglia della strategia {strategy}")\n    if rs is not None and rs < 60: flags.append("high yield: maggiore rischio di default")\n    if m["mod_duration"] > max_dur: flags.append(f"duration {m[\'mod_duration\']:.1f} oltre soglia strategia {strategy}")\n    if m["years_to_maturity"] < 0.25: flags.append("scadenza imminente")\n    if b.ytm_override is not None and abs(calc_ytm - b.ytm_override) > 0.003: flags.append(f"scarto tra calcolo ({calc_ytm:.2%}) e dato Borsa Italiana ({b.ytm_override:.2%})")\n    excessive = any(("sotto la soglia" in x) or ("oltre soglia" in x) or ("non disponibile" in x) or ("imminente" in x) for x in flags)\n    return ScoreResult("titan_bonds", score, eff_f, "missing" if score is None else "estimated", missing, b.price_date or date.today(),\n                       MODEL_VERSION, {**{k: (round(v, 5) if isinstance(v, float) else v) for k, v in m.items()},\n                                       "flags": flags, "excessive": excessive, "liquidity": "non disponibile (spread/volumi non forniti)"})\n\n\ndef load_csv(path: str) -> dict[str, BondSnapshot]:\n    """CSV: isin,name,issuer_type,currency,coupon,maturity,price,rating,frequency,price_date"""\n    import csv\n    out = {}\n    for r in csv.DictReader(open(path, encoding="utf-8-sig")):\n        out[r["isin"].strip().upper()] = BondSnapshot(\n            r["isin"].strip().upper(), r["name"], r["currency"], float(r["coupon"]), date.fromisoformat(r["maturity"]), float(r["price"]),\n            r.get("issuer_type") or "govt", r.get("rating") or None, int(r.get("frequency") or 1), None,\n            date.fromisoformat(r["price_date"]) if r.get("price_date") else None)\n    return out\n', False), 'app.engines.etf': ('"""Titan ETF: valuta costi, tracking, dimensione, liquidità e andamento con DATI REALI di Borsa Italiana/emittente.\nUn fattore senza dato resta \'n/d\' (mai inventato) e i pesi si rinormalizzano; servono almeno 3 fattori."""\nfrom __future__ import annotations\nimport math\nfrom dataclasses import dataclass, field, asdict\nfrom ..core.scoring import Factor, ScoreResult, combine, Strategy\n\nMODEL_VERSION = "etf-1.0.0"\n\n\n@dataclass\nclass EtfRecord:\n    isin: str\n    ticker: str\n    name: str = ""\n    mic: str | None = None               # ETFP = ETFplus Borsa Italiana\n    trade_ccy: str | None = None         # valuta di negoziazione\n    fund_ccy: str | None = None          # valuta di denominazione del fondo\n    domicile: str | None = None\n    benchmark: str | None = None\n    issuer: str | None = None\n    segment: str | None = None\n    bi_class: str | None = None          # es. \'Classe 2 Ind Azionario\' (Borsa Italiana)\n    bi_area: str | None = None           # es. \'EQUITY WORLD\' (Area Benchmark)\n    distribution: str | None = None      # acc | dist\n    replication: str | None = None\n    ter_pct: float | None = None\n    aum: float | None = None\n    aum_ccy: str | None = None\n    last_price: float | None = None\n    last_date: str | None = None         # ISO\n    volume: float | None = None\n    turnover: float | None = None        # controvalore della seduta (valuta di negoziazione)\n    trades: float | None = None\n    turnover_month_m: float | None = None   # scambi del mese in milioni di euro (statistiche ufficiali Borsa Italiana)\n    spread_pct: float | None = None         # spread medio su ordine da 25.000 euro (statistiche ufficiali)\n    trades_month: float | None = None\n    perf_1m: float | None = None\n    perf_6m: float | None = None\n    perf_ytd: float | None = None\n    perf_1y: float | None = None\n    high_52w: float | None = None\n    low_52w: float | None = None\n    tracking_diff_pp: dict | None = None  # es. {"1y": 0.01, "3y": 0.03} punti percentuali, fondo - benchmark\n    asof: str = ""\n    sources: list = field(default_factory=list)\n    notes: list = field(default_factory=list)\n\n\nW = {  # costo, tracking, dimensione, liquidita, spread, momentum, posizione 52 settimane\n    "prudente":   (.22, .17, .12, .17, .12, .10, .10),\n    "bilanciata": (.20, .14, .10, .15, .10, .19, .12),\n    "aggressiva": (.10, .07, .04, .13, .08, .38, .20),\n}\n\n\ndef _clip(x, lo=0.0, hi=100.0):\n    return float(max(lo, min(hi, x)))\n\n\ndef analyze(r: EtfRecord, strategy: Strategy = "bilanciata") -> ScoreResult:\n    w, f, flags, info = W[strategy], [], [], []\n    f.append(Factor("costo_ter", r.ter_pct, None if r.ter_pct is None else _clip(100 - (r.ter_pct - 0.07) / 0.93 * 100), w[0],\n                    "TER annuo" + ("" if r.ter_pct is None else f" {r.ter_pct:.2f}% (100 punti fino a 0,07%, 0 punti da 1,00%)")))\n    td = None if not r.tracking_diff_pp else (r.tracking_diff_pp.get("3y") if r.tracking_diff_pp.get("3y") is not None else r.tracking_diff_pp.get("1y"))\n    f.append(Factor("tracking_difference", td, None if td is None else _clip(100 - (abs(td) - 0.10) / 0.90 * 100), w[1],\n                    "scostamento fondo-indice" + ("" if td is None else f" {td:+.2f} punti % (emittente)")))\n    f.append(Factor("dimensione", r.aum, None if not r.aum else _clip(35 + 35 * math.log10(r.aum / 1e8)), w[2],\n                    "patrimonio (ordine di grandezza, valuta non convertita)"))\n    liq = r.turnover_month_m * 1e6 / 21 if r.turnover_month_m else r.turnover\n    f.append(Factor("liquidita", liq, None if not liq else _clip(60 + 40 * math.log10(max(liq, 1) / 1e6)), w[3],\n                    "controvalore medio giornaliero" + (" (da scambi mensili ufficiali)" if r.turnover_month_m else " (sola ultima seduta, stima)")))\n    f.append(Factor("spread", r.spread_pct, None if r.spread_pct is None else _clip(100 - (r.spread_pct - 0.03) / 0.47 * 100), w[4],\n                    "spread medio denaro-lettera su ordine da 25.000 euro" + ("" if r.spread_pct is None else f": {r.spread_pct:.3f}%")))\n    f.append(Factor("momentum_6m", r.perf_6m, None if r.perf_6m is None else _clip(50 + 2.5 * r.perf_6m), w[5],\n                    "performance 6 mesi (Borsa Italiana)"))\n    pos = None\n    if r.last_price and r.high_52w and r.low_52w and r.high_52w > r.low_52w:\n        pos = (r.last_price - r.low_52w) / (r.high_52w - r.low_52w) * 100\n    f.append(Factor("posizione_52w", None if pos is None else round(pos, 1), None if pos is None else _clip(pos), w[6],\n                    "posizione nel range minimo-massimo a 52 settimane"))\n    score, eff, missing = combine(f)\n    if r.ter_pct is not None and r.ter_pct > 0.60: flags.append(f"costi elevati: TER {r.ter_pct:.2f}%")\n    if r.turnover is not None and r.turnover < 50_000: flags.append("liquidità bassa nell\'ultima seduta")\n    if r.fund_ccy and r.trade_ccy and r.fund_ccy != r.trade_ccy: flags.append(f"rischio cambio: fondo in {r.fund_ccy}, negoziato in {r.trade_ccy}")\n    if not r.trade_ccy: info.append("valuta di negoziazione non verificata")\n    if r.spread_pct is None: info.append("spread denaro-lettera non disponibile")\n    if r.spread_pct is not None and r.spread_pct > 0.30: flags.append(f"spread elevato: {r.spread_pct:.2f}%")\n    return ScoreResult("titan_etf", score, eff, "missing" if score is None else "estimated", missing,\n                       None, MODEL_VERSION, {"flags": flags, "info": info, "excessive": bool(r.ter_pct and r.ter_pct > 1.0)})\n\n\ndef record_dict(r: EtfRecord) -> dict:\n    return asdict(r)\n', False), 'app.engines.fundamentals': ('"""Titan Fundamentals (azioni). Distingue dati storici/correnti da STIME degli analisti.\nInput normalizzato: FundamentalSnapshot. Il mapper EODHD è difensivo ma NON verificato su dati reali."""\nfrom __future__ import annotations\nfrom dataclasses import dataclass, field\nfrom datetime import date\nimport pandas as pd\nfrom ..core.scoring import Factor, ScoreResult, combine, Strategy\n\nMODEL_VERSION = "fundamentals-1.0.0"\nSTALE_DAYS = 456  # ~15 mesi: bilancio considerato datato\n\n\n@dataclass\nclass FundamentalSnapshot:\n    period_end: date\n    sector: str | None = None\n    revenue: list[float] = field(default_factory=list)      # annuali, dal più vecchio al più recente (storico)\n    ebitda: float | None = None\n    net_income: float | None = None\n    fcf: float | None = None\n    net_debt: float | None = None\n    roe: float | None = None\n    op_margin: float | None = None\n    pe: float | None = None               # corrente (prezzo / utili ultimi 12 mesi)\n    forward_pe: float | None = None       # STIMA analisti\n    peg: float | None = None              # STIMA analisti\n    ps: float | None = None\n    pb: float | None = None\n    dividend_yield: float | None = None\n    dps_history: list[float] = field(default_factory=list)\n    estimate_keys: tuple[str, ...] = ("forward_pe", "peg")\n\n\ndef _clip(x, lo=0.0, hi=100.0):\n    return float(max(lo, min(hi, x)))\n\n\nW = {  # growth, profitability, balance, cashflow, valuation, dividends\n    "prudente":   (.10, .20, .25, .20, .15, .10),\n    "bilanciata": (.20, .20, .15, .15, .25, .05),\n    "aggressiva": (.40, .15, .05, .15, .20, .05),\n}\n\n\ndef analyze(s: FundamentalSnapshot, strategy: Strategy = "bilanciata", sector_medians: dict | None = None,\n            today: date | None = None) -> ScoreResult:\n    today = today or date.today()\n    w, f, used_est = W[strategy], [], []\n\n    # crescita ricavi (CAGR sugli anni disponibili, serve >= 3 punti)\n    if len(s.revenue) >= 3 and s.revenue[0] > 0:\n        n = len(s.revenue) - 1\n        cagr = (s.revenue[-1] / s.revenue[0]) ** (1 / n) - 1\n        f.append(Factor("crescita_ricavi", round(cagr, 4), _clip(35 + cagr * 400), w[0], f"CAGR ricavi su {n} anni (storico)"))\n    else:\n        f.append(Factor("crescita_ricavi", None, None, w[0], "serie ricavi insufficiente"))\n\n    # redditività\n    parts = [v for v in (None if s.roe is None else _clip(s.roe / 0.25 * 100),\n                         None if s.op_margin is None else _clip(s.op_margin / 0.30 * 100)) if v is not None]\n    f.append(Factor("redditivita", s.roe, sum(parts) / len(parts) if parts else None, w[1], "ROE e margine operativo"))\n\n    # solidità patrimoniale\n    if s.net_debt is not None and s.ebitda is not None:\n        if s.ebitda <= 0:\n            f.append(Factor("solidita", None, 0.0, w[2], "EBITDA non positivo: debito non sostenibile"))\n        else:\n            nd = s.net_debt / s.ebitda\n            f.append(Factor("solidita", round(nd, 2), _clip(100 - max(nd, 0) / 6 * 100), w[2], f"debito netto/EBITDA = {nd:.2f}"))\n    else:\n        f.append(Factor("solidita", None, None, w[2], "debito netto o EBITDA mancanti"))\n\n    # flussi di cassa\n    if s.fcf is not None and s.revenue:\n        m = s.fcf / s.revenue[-1]\n        conv = None if not s.net_income or s.net_income <= 0 else s.fcf / s.net_income\n        sc = _clip(m / 0.15 * 100) if conv is None else 0.6 * _clip(m / 0.15 * 100) + 0.4 * _clip(conv / 1.0 * 100)\n        f.append(Factor("flussi_cassa", round(m, 4), sc, w[3], f"FCF margin {m:.1%}" + ("" if conv is None else f", conversione utile {conv:.0%}")))\n    else:\n        f.append(Factor("flussi_cassa", None, None, w[3], "FCF mancante"))\n\n    # valutazione: relativa al settore se disponibile, altrimenti assoluta\n    vals = []\n    pe_used, pe_key = (s.forward_pe, "forward_pe") if s.forward_pe else (s.pe, "pe")\n    if pe_used and pe_used > 0:\n        med = (sector_medians or {}).get(pe_key) or (sector_medians or {}).get("pe")\n        vals.append(_clip(55 - (pe_used / med - 1) * 80) if med else _clip(100 - (pe_used - 8) / 32 * 100))\n        if pe_key in s.estimate_keys: used_est.append(pe_key)\n    if s.peg and s.peg > 0:\n        vals.append(_clip(100 - (s.peg - 0.5) / 2.0 * 100)); used_est.append("peg")\n    f.append(Factor("valutazione", pe_used, sum(vals) / len(vals) if vals else None, w[4],\n                    "P/E" + (" forward (stima analisti)" if pe_key == "forward_pe" else " corrente") + (" vs mediana settore" if sector_medians else " (soglie assolute)")))\n\n    # dividendi (non penalizza chi non paga: fattore escluso)\n    if s.dividend_yield:\n        g = None\n        if len(s.dps_history) >= 3 and s.dps_history[0] > 0:\n            g = (s.dps_history[-1] / s.dps_history[0]) ** (1 / (len(s.dps_history) - 1)) - 1\n        sc = _clip(s.dividend_yield / 0.05 * 70) * (0.6 if g is None else 0.5) + (0 if g is None else _clip(50 + g * 500) * 0.5)\n        f.append(Factor("dividendi", s.dividend_yield, _clip(sc if g is not None else sc / 0.6 * 0.6 + 20), w[5], "rendimento e crescita DPS"))\n    else:\n        f.append(Factor("dividendi", None, None, w[5], "non distribuisce dividendi (fattore non applicato)"))\n\n    score, eff, missing = combine(f)\n    stale = (today - s.period_end).days > STALE_DAYS\n    quality = "missing" if score is None else ("estimated" if (used_est or stale) else "delayed")\n    return ScoreResult("titan_fundamentals", score, eff, quality, missing, s.period_end, MODEL_VERSION,\n                       {"stale_statements": stale, "estimates_used": sorted(set(used_est)), "sector": s.sector,\n                        "data_kinds": {"storico": ["crescita_ricavi", "redditivita", "solidita", "flussi_cassa"],\n                                       "stime_analisti": sorted(set(used_est))}})\n\n\ndef from_eodhd(raw: dict) -> FundamentalSnapshot:\n    """Mappa il JSON /fundamentals di EODHD. ATTENZIONE: struttura da verificare sulla documentazione/account."""\n    g = lambda d, *k: _dig(d, *k)\n    inc = g(raw, "Financials", "Income_Statement", "yearly") or {}\n    cf = g(raw, "Financials", "Cash_Flow", "yearly") or {}\n    bs = g(raw, "Financials", "Balance_Sheet", "yearly") or {}\n    dates = sorted(inc.keys())\n    rev = [float(inc[d]["totalRevenue"]) for d in dates if inc[d].get("totalRevenue") not in (None, "None")][-5:]\n    last = dates[-1] if dates else None\n    num = lambda v: None if v in (None, "None", "") else float(v)\n    hl, va = raw.get("Highlights", {}), raw.get("Valuation", {})\n    return FundamentalSnapshot(\n        period_end=date.fromisoformat(last) if last else date(1970, 1, 1), sector=g(raw, "General", "Sector"),\n        revenue=rev, ebitda=num(hl.get("EBITDA")), net_income=num(inc[last].get("netIncome")) if last else None,\n        fcf=num(cf[sorted(cf)[-1]].get("freeCashFlow")) if cf else None,\n        net_debt=num(bs[sorted(bs)[-1]].get("netDebt")) if bs else None,\n        roe=num(hl.get("ReturnOnEquityTTM")), op_margin=num(hl.get("OperatingMarginTTM")), pe=num(hl.get("PERatio")),\n        forward_pe=num(va.get("ForwardPE")), peg=num(hl.get("PEGRatio")), ps=num(va.get("PriceSalesTTM")),\n        pb=num(va.get("PriceBookMRQ")), dividend_yield=num(hl.get("DividendYield")))\n\n\ndef _dig(d, *keys):\n    for k in keys:\n        if not isinstance(d, dict): return None\n        d = d.get(k)\n    return d\n', False), 'app.engines.indicators': ('"""Indicatori tecnici puri (pandas/numpy). Nessun LLM: solo calcolo deterministico."""\nimport numpy as np\nimport pandas as pd\n\n\ndef sma(s: pd.Series, n: int) -> pd.Series:\n    return s.rolling(n, min_periods=n).mean()\n\n\ndef ema(s: pd.Series, n: int) -> pd.Series:\n    return s.ewm(span=n, adjust=False, min_periods=n).mean()\n\n\ndef rsi(close: pd.Series, n: int = 14) -> pd.Series:\n    d = close.diff()\n    up = d.clip(lower=0).ewm(alpha=1 / n, adjust=False, min_periods=n).mean()\n    dn = (-d.clip(upper=0)).ewm(alpha=1 / n, adjust=False, min_periods=n).mean()\n    rs = up / dn.replace(0, np.nan)\n    out = 100 - 100 / (1 + rs)\n    return out.where(dn != 0, 100.0).where(up.notna())\n\n\ndef macd(close: pd.Series, fast=12, slow=26, sig=9):\n    line = ema(close, fast) - ema(close, slow)\n    signal = line.ewm(span=sig, adjust=False, min_periods=sig).mean()\n    return line, signal, line - signal\n\n\ndef bollinger(close: pd.Series, n=20, k=2.0):\n    mid = sma(close, n)\n    sd = close.rolling(n, min_periods=n).std(ddof=0)\n    upper, lower = mid + k * sd, mid - k * sd\n    pct_b = (close - lower) / (upper - lower).replace(0, np.nan)\n    return mid, upper, lower, pct_b\n\n\ndef atr(df: pd.DataFrame, n: int = 14) -> pd.Series:\n    pc = df["close"].shift()\n    tr = pd.concat([df["high"] - df["low"], (df["high"] - pc).abs(), (df["low"] - pc).abs()], axis=1).max(axis=1)\n    return tr.ewm(alpha=1 / n, adjust=False, min_periods=n).mean()\n\n\ndef hist_vol(close: pd.Series, n: int = 60) -> pd.Series:\n    """Volatilità storica annualizzata (rendimenti log giornalieri)."""\n    r = np.log(close).diff()\n    return r.rolling(n, min_periods=n).std(ddof=1) * np.sqrt(252)\n\n\ndef max_drawdown(close: pd.Series) -> float:\n    return float((close / close.cummax() - 1).min())\n\n\ndef resample_ohlcv(df: pd.DataFrame, rule: str) -> pd.DataFrame:\n    """rule: \'W\' settimanale, \'M\'/\'ME\' mensile."""\n    agg = {"open": "first", "high": "max", "low": "min", "close": "last", "volume": "sum"}\n    return df.resample(rule).agg(agg).dropna(subset=["close"])\n', False), 'app.engines.portfolio': ('"""Portfolio Simulator: portafogli VIRTUALI (nessuna operazione reale). Calcoli deterministici su prezzi storici."""\nfrom __future__ import annotations\nimport numpy as np\nimport pandas as pd\n\nTD = 252\n\n\ndef simulate(closes: dict[str, pd.Series], weights: dict[str, float], capital: float = 10_000.0, rebalance: str = "annual",\n             currencies: dict[str, str] | None = None, bench: pd.Series | None = None, mc_paths: int = 2000,\n             mc_days: int = 252, seed: int = 42) -> dict:\n    warnings: list[str] = []\n    tot = sum(weights.values())\n    if tot <= 0 or any(w < 0 for w in weights.values()):\n        raise ValueError("pesi non validi")\n    if abs(tot - 100) > 0.01:\n        warnings.append(f"i pesi sommavano a {tot:.1f}%: normalizzati a 100%")\n    w = pd.Series({k: v / tot for k, v in weights.items()})\n    px = pd.DataFrame({k: closes[k] for k in w.index}).dropna()\n    if len(px) < 60:\n        raise ValueError("storico comune insufficiente (<60 sedute)")\n    if len(px) < TD:\n        warnings.append(f"storico comune di soli {len(px)} giorni: metriche poco affidabili")\n    ccy = set((currencies or {}).get(k, "?") for k in w.index)\n    if len(ccy) > 1:\n        warnings.append("strumenti in valute diverse: valori NON convertiti in una valuta comune, rischio cambio non modellato")\n    big = [k for k, v in w.items() if v > 0.40]\n    if big:\n        warnings.append(f"concentrazione elevata (>40%): {\', \'.join(big)}")\n    warnings.append("selezione basata su strumenti attuali: possibile survivorship bias nei risultati storici")\n\n    r = px.pct_change().dropna()\n    n_assets = len(w)\n    # equity curve con ribilanciamento\n    step = {"none": None, "annual": 252, "quarterly": 63, "monthly": 21}[rebalance]\n    hold = (w * capital).values.astype(float)\n    eq = []\n    for i, row in enumerate(r.values):\n        hold = hold * (1 + row)\n        if step and (i + 1) % step == 0:\n            hold = hold.sum() * w.values\n        eq.append(hold.sum())\n    eq = pd.Series(eq, index=r.index)\n    pr = eq.pct_change().fillna(eq.iloc[0] / capital - 1)\n    years = len(eq) / TD\n    total = float(eq.iloc[-1] / capital - 1)\n    vol = float(pr.std(ddof=1) * np.sqrt(TD))\n    cagr = float((eq.iloc[-1] / capital) ** (1 / years) - 1) if years > 0 else None\n    mdd = float((eq / eq.cummax() - 1).min())\n    cov = r.cov().values * TD\n    wv = w.values\n    pvol = float(np.sqrt(wv @ cov @ wv))\n    rc = (wv * (cov @ wv)) / (pvol ** 2) if pvol > 0 else np.zeros(n_assets)\n    indiv_vol = np.sqrt(np.diag(cov))\n    out = {\n        "metrics": {"total_return": round(total, 4), "cagr": None if cagr is None else round(cagr, 4), "volatility": round(vol, 4),\n                    "max_drawdown": round(mdd, 4), "sharpe_rf0": round(cagr / vol, 3) if cagr is not None and vol > 0 else None,\n                    "worst_day": round(float(pr.min()), 4), "worst_20d": round(float(eq.pct_change(20).min()), 4),\n                    "effective_n": round(float(1 / (wv ** 2).sum()), 2),\n                    "diversification_ratio": round(float((wv @ indiv_vol) / pvol), 3) if pvol > 0 else None,\n                    "history_days": len(eq), "start": eq.index[0].strftime("%Y-%m-%d"), "end": eq.index[-1].strftime("%Y-%m-%d")},\n        "risk_contribution": {k: round(float(v), 4) for k, v in zip(w.index, rc)},\n        "correlation": {"labels": list(w.index), "matrix": r.corr().round(3).values.tolist()},\n        "equity": [{"time": i.strftime("%Y-%m-%d"), "value": round(float(v), 2)} for i, v in eq.items()],\n        "rebalance": rebalance, "warnings": warnings,\n    }\n    if bench is not None:\n        b = bench.reindex(px.index).dropna()\n        if len(b) > 60:\n            out["metrics"]["benchmark_return_same_period"] = round(float(b.iloc[-1] / b.iloc[0] - 1), 4)\n    # scenari futuri: bootstrap a blocchi dei rendimenti storici del portafoglio (NON è una previsione)\n    rng = np.random.default_rng(seed)\n    blk = 20\n    arr = pr.values\n    nb = int(np.ceil(mc_days / blk))\n    starts = rng.integers(0, max(len(arr) - blk, 1), size=(mc_paths, nb))\n    paths = np.stack([np.concatenate([arr[s:s + blk] for s in row])[:mc_days] for row in starts])\n    cum = capital * np.cumprod(1 + paths, axis=1)\n    q = np.percentile(cum, [5, 50, 95], axis=0)\n    out["scenarios"] = {"horizon_days": mc_days, "paths": mc_paths, "method": "bootstrap a blocchi di rendimenti storici (non previsione)",\n                        "p5_final": round(float(q[0, -1]), 2), "p50_final": round(float(q[1, -1]), 2), "p95_final": round(float(q[2, -1]), 2),\n                        "prob_loss": round(float((cum[:, -1] < capital).mean()), 3),\n                        "fan": [{"day": int(d), "p5": round(float(q[0, d]), 2), "p50": round(float(q[1, d]), 2), "p95": round(float(q[2, d]), 2)}\n                                for d in range(0, mc_days, max(mc_days // 24, 1))],\n                        "disclaimer": "I percorsi simulati ricampionano il passato: il futuro può essere molto diverso. Nessun rendimento è garantito."}\n    return out\n', False), 'app.engines.quant': ('"""Titan Quant: statistiche rendimento/rischio calcolate da algoritmi (mai dall\'LLM)."""\nfrom __future__ import annotations\nimport numpy as np\nimport pandas as pd\nfrom ..core.scoring import Factor, ScoreResult, combine, Strategy\n\nMODEL_VERSION = "quant-1.0.0"\nTD = 252\n\n\ndef _clip(x, lo=0.0, hi=100.0):\n    return float(max(lo, min(hi, x)))\n\n\ndef metrics(close: pd.Series, bench: pd.Series | None = None, rf: float = 0.0) -> dict:\n    r = close.pct_change().dropna()\n    out: dict = {}\n    if len(close) >= TD + 1:\n        y = r.iloc[-TD:]\n        ann_ret = float(close.iloc[-1] / close.iloc[-TD - 1] - 1)\n        vol = float(y.std(ddof=1) * np.sqrt(TD))\n        dn = y[y < 0]\n        dvol = float(np.sqrt((dn ** 2).sum() / len(y)) * np.sqrt(TD)) if len(dn) else np.nan\n        out.update(ret_1y=ann_ret, vol_1y=vol,\n                   sharpe=(ann_ret - rf) / vol if vol > 0 else np.nan,\n                   sortino=(ann_ret - rf) / dvol if dvol and dvol > 0 else np.nan)\n        m = close.resample("ME").last().pct_change().dropna().iloc[-12:]\n        out["hit_rate_m"] = float((m > 0).mean()) if len(m) >= 6 else np.nan\n        mdd = float((close.iloc[-TD:] / close.iloc[-TD:].cummax() - 1).min())\n        out["max_dd_1y"] = mdd\n        out["calmar"] = ann_ret / abs(mdd) if mdd < 0 else np.nan\n    if len(close) >= 253:\n        out["mom_12_1"] = float(close.iloc[-22] / close.iloc[-253] - 1)  # esclude l\'ultimo mese\n    if bench is not None and out:\n        b = bench.pct_change().reindex(r.index).dropna()\n        j = pd.concat([r, b], axis=1, join="inner").iloc[-TD:].dropna()\n        if len(j) > 120 and j.iloc[:, 1].var() > 0:\n            out["beta"] = float(j.cov().iloc[0, 1] / j.iloc[:, 1].var())\n            out["corr_bench"] = float(j.corr().iloc[0, 1])\n    return out\n\n\ndef analyze(close: pd.Series, bench: pd.Series | None = None, strategy: Strategy = "bilanciata") -> ScoreResult:\n    m = metrics(close, bench)\n    W = {"prudente": (.20, .10, .20, .50), "bilanciata": (.30, .25, .20, .25), "aggressiva": (.25, .50, .15, .10)}[strategy]\n    g = lambda k: m.get(k) if m.get(k) is not None and not pd.isna(m.get(k)) else None\n    f = []\n    s = g("sharpe");  f.append(Factor("sharpe_1y", s, None if s is None else _clip(50 + s * 35), W[0], "Sharpe 1a (rf=0, semplificato)"))\n    mo = g("mom_12_1"); f.append(Factor("momentum_12_1", mo, None if mo is None else _clip(50 + mo * 150), W[1], "rendimento 12 mesi escluso ultimo mese"))\n    so = g("sortino"); f.append(Factor("sortino_1y", so, None if so is None else _clip(50 + so * 30), W[2], "rendimento/volatilità ribassista"))\n    hr = g("hit_rate_m"); f.append(Factor("consistency", hr, None if hr is None else _clip(hr * 100), W[3], "% mesi positivi ultimi 12"))\n    score, eff, missing = combine(f)\n    return ScoreResult("titan_quant", score, eff, "missing" if score is None else ("delayed" if not missing else "estimated"),\n                       missing, close.index[-1].date() if len(close) else None, MODEL_VERSION,\n                       {k: (None if pd.isna(v) else round(float(v), 4)) for k, v in m.items()})\n', False), 'app.engines.risk': ('"""Titan Risk: punteggio di sicurezza (alto = meno rischioso) + segnalazioni di rischio eccessivo."""\nfrom __future__ import annotations\nimport numpy as np\nimport pandas as pd\nfrom . import indicators as ind\nfrom ..core.scoring import Factor, ScoreResult, combine, Strategy\n\nMODEL_VERSION = "risk-1.0.0"\n\n\ndef _clip(x, lo=0.0, hi=100.0):\n    return float(max(lo, min(hi, x)))\n\n\n# soglie di esclusione per strategia: (vol annua max, drawdown 1a max assoluto)\nLIMITS = {"prudente": (0.20, 0.25), "bilanciata": (0.35, 0.40), "aggressiva": (0.65, 0.60)}\nMIN_TURNOVER = 100_000  # controvalore medio giornaliero minimo (valuta di negoziazione)\n\n\ndef analyze(df: pd.DataFrame, strategy: Strategy = "bilanciata", fx_unhedged: bool | None = None) -> ScoreResult:\n    c = df["close"]\n    f, flags = [], []\n    vol_max, dd_max = LIMITS[strategy]\n    vol = ind.hist_vol(c, 60).dropna()\n    vol_v = float(vol.iloc[-1]) if len(vol) else None\n    dd = ind.max_drawdown(c.iloc[-252:]) if len(c) >= 252 else None\n    r = np.log(c).diff().dropna().iloc[-252:]\n    cvar = float(r[r <= r.quantile(.05)].mean()) if len(r) >= 120 else None\n    turn = float((df["close"] * df["volume"]).iloc[-60:].median()) if len(c) >= 60 and df["volume"].sum() > 0 else None\n\n    f.append(Factor("volatilita", vol_v, None if vol_v is None else _clip(100 - vol_v / vol_max * 60), .30, "vol annua 60g"))\n    f.append(Factor("drawdown", dd, None if dd is None else _clip(100 - abs(dd) / dd_max * 60), .30, "max drawdown 1a"))\n    f.append(Factor("coda_cvar5", cvar, None if cvar is None else _clip(100 - abs(cvar) / 0.05 * 60), .20, "perdita media giornaliera nel peggior 5%"))\n    f.append(Factor("liquidita", turn, None if turn is None else _clip(np.log10(max(turn, 1) / MIN_TURNOVER) * 50 + 50), .20,\n                    "controvalore mediano 60g (spread bid-ask non disponibile da dati EOD)"))\n    if vol_v is not None and vol_v > vol_max: flags.append(f"volatilità {vol_v:.0%} oltre soglia strategia {strategy}")\n    if dd is not None and abs(dd) > dd_max: flags.append(f"drawdown 1a {dd:.0%} oltre soglia strategia {strategy}")\n    if turn is not None and turn < MIN_TURNOVER: flags.append("liquidità insufficiente")\n    if len(c) < 252: flags.append("storico < 1 anno: valutazione poco affidabile")\n    if fx_unhedged: flags.append("rischio cambio non coperto")\n    score, eff, missing = combine(f)\n    return ScoreResult("titan_risk", score, eff, "missing" if score is None else ("delayed" if not missing else "estimated"),\n                       missing, c.index[-1].date(), MODEL_VERSION,\n                       {"flags": flags, "excessive": bool(flags) and any("soglia" in x or "insufficiente" in x or "poco affidabile" in x for x in flags),\n                        "spread_bid_ask": None})\n\n\ndef correlation_matrix(closes: dict[str, pd.Series], window: int = 252) -> pd.DataFrame:\n    rets = pd.DataFrame({k: v.pct_change() for k, v in closes.items()}).dropna().iloc[-window:]\n    return rets.corr().round(3)\n', False), 'app.engines.technical': ('"""Titan Technical: analisi su grafici giornalieri/settimanali/mensili (no intraday).\nOgni fattore 0-100; i pesi dipendono dalla strategia; pesi rinormalizzati se mancano dati."""\nfrom __future__ import annotations\nimport numpy as np\nimport pandas as pd\nfrom . import indicators as ind\nfrom ..core.scoring import Factor, ScoreResult, combine, Strategy\n\nMODEL_VERSION = "technical-1.0.0"\n\nWEIGHTS: dict[str, dict[str, float]] = {\n    "prudente":   {"trend": .30, "momentum": .10, "rel_strength": .15, "risk": .30, "volume": .05, "structure": .10},\n    "bilanciata": {"trend": .30, "momentum": .20, "rel_strength": .20, "risk": .15, "volume": .05, "structure": .10},\n    "aggressiva": {"trend": .20, "momentum": .30, "rel_strength": .25, "risk": .05, "volume": .10, "structure": .10},\n}\n\n\ndef _clip(x: float, lo=0.0, hi=100.0) -> float:\n    return float(max(lo, min(hi, x)))\n\n\ndef _last(s: pd.Series):\n    v = s.dropna()\n    return float(v.iloc[-1]) if len(v) else None\n\n\ndef validate(df: pd.DataFrame) -> pd.DataFrame:\n    need = {"open", "high", "low", "close", "volume"}\n    if not need.issubset(df.columns):\n        raise ValueError(f"colonne mancanti: {need - set(df.columns)}")\n    if not isinstance(df.index, pd.DatetimeIndex):\n        raise ValueError("indice deve essere DatetimeIndex")\n    df = df.sort_index()\n    df = df[~df.index.duplicated(keep="last")]\n    return df.dropna(subset=["close"])\n\n\ndef analyze(df: pd.DataFrame, benchmark: pd.Series | None = None,\n            strategy: Strategy = "bilanciata") -> ScoreResult:\n    df = validate(df)\n    c = df["close"]\n    w = WEIGHTS[strategy]\n    f: list[Factor] = []\n\n    # --- TREND (giornaliero + conferma settimanale) ---\n    s50, s200 = ind.sma(c, 50), ind.sma(c, 200)\n    last, l50, l200 = float(c.iloc[-1]), _last(s50), _last(s200)\n    if l50 is not None and l200 is not None and len(c) >= 220:\n        pts = [last > l50, last > l200, l50 > l200, bool(s200.iloc[-1] > s200.iloc[-21])]\n        wc = ind.resample_ohlcv(df, "W")["close"]\n        wk = ind.sma(wc, 30).dropna()\n        pts.append(bool(len(wk) and float(wc.iloc[-1]) > float(wk.iloc[-1])))\n        f.append(Factor("trend", round(sum(pts) / len(pts), 2), 100 * sum(pts) / len(pts), w["trend"],\n                        "prezzo>SMA50, >SMA200, SMA50>SMA200, SMA200 in salita, conferma settimanale"))\n    else:\n        f.append(Factor("trend", None, None, w["trend"], "storico insufficiente (<220 sedute)"))\n\n    # --- MOMENTUM (RSI + MACD) ---\n    r = _last(ind.rsi(c))\n    _, _, hist = ind.macd(c)\n    hd = hist.dropna()\n    if r is not None and len(hd) > 4:\n        h_now, h_prev = float(hd.iloc[-1]), float(hd.iloc[-4])\n        rs = 100 - abs(r - 60) * 2.5 if r <= 80 else max(0, 50 - (r - 80) * 3)\n        ms = 50 + (25 if h_now > 0 else -25) + (25 if h_now > h_prev else -25)\n        f.append(Factor("momentum", round(r, 1), _clip(0.5 * rs + 0.5 * ms), w["momentum"],\n                        f"RSI14={r:.1f}; MACD hist {\'>\' if h_now > 0 else \'<\'}0, {\'in rafforzamento\' if h_now > h_prev else \'in indebolimento\'}"))\n    else:\n        f.append(Factor("momentum", None, None, w["momentum"], "dati insufficienti"))\n\n    # --- FORZA RELATIVA vs benchmark (63 sedute ~ 3 mesi) ---\n    if benchmark is not None:\n        b = benchmark.reindex(c.index).ffill().dropna()\n        if len(b) > 64 and len(c) > 64:\n            diff = float(c.iloc[-1] / c.iloc[-64] - 1) - float(b.iloc[-1] / b.iloc[-64] - 1)\n            f.append(Factor("rel_strength", round(diff, 4), _clip((diff + 0.20) / 0.40 * 100), w["rel_strength"],\n                            f"sovra/sotto-performance 3m vs benchmark: {diff:+.1%}"))\n        else:\n            f.append(Factor("rel_strength", None, None, w["rel_strength"], "benchmark insufficiente"))\n    else:\n        f.append(Factor("rel_strength", None, None, w["rel_strength"], "benchmark non fornito"))\n\n    # --- RISCHIO (volatilità + drawdown 1y): più basso = punteggio più alto ---\n    vol = _last(ind.hist_vol(c))\n    if vol is not None and len(c) >= 252:\n        mdd = ind.max_drawdown(c.iloc[-252:])\n        vs = _clip(100 - (vol - 0.10) / 0.50 * 100)\n        ds = _clip(100 - abs(mdd) / 0.40 * 100)\n        f.append(Factor("risk", round(vol, 4), 0.6 * vs + 0.4 * ds, w["risk"],\n                        f"vol annua 60g={vol:.1%}, max drawdown 1a={mdd:.1%}"))\n    else:\n        f.append(Factor("risk", None, None, w["risk"], "storico <252 sedute"))\n\n    # --- VOLUMI (conferma del movimento) ---\n    v = df["volume"].replace(0, np.nan)\n    if v.notna().sum() >= 60 and len(c) >= 60:\n        ratio = float(v.iloc[-20:].mean() / v.iloc[-60:].mean())\n        up = float(c.iloc[-1] / c.iloc[-20] - 1) > 0\n        vs = _clip(50 + (ratio - 1) * 100 * (1 if up else -1))\n        f.append(Factor("volume", round(ratio, 2), vs, w["volume"],\n                        f"volume 20g/60g={ratio:.2f} con prezzo {\'in salita\' if up else \'in discesa\'}"))\n    else:\n        f.append(Factor("volume", None, None, w["volume"], "volumi non disponibili"))\n\n    # --- STRUTTURA: supporto/resistenza, breakout e falsi breakout ---\n    la = _last(ind.atr(df))\n    support = None\n    if la is not None and len(c) >= 63:\n        support = float(df["low"].iloc[-60:].min())\n        res_prev = float(df["high"].iloc[-61:-1].max())\n        res_before = float(df["high"].iloc[-62:-2].max())\n        dist_atr = (last - support) / la\n        broke = last > res_prev\n        false_bo = float(c.iloc[-2]) > res_before and last < res_before\n        sc = 50.0 + (25 if broke else 0) - (30 if false_bo else 0)\n        sc += 15 if 0.5 <= dist_atr <= 3 else (-10 if dist_atr > 8 else 0)\n        f.append(Factor("structure", round(dist_atr, 2), _clip(sc), w["structure"],\n                        f"{dist_atr:.1f} ATR sopra supporto 60g; breakout={\'sì\' if broke else \'no\'}; falso breakout={\'sì\' if false_bo else \'no\'}"))\n    else:\n        f.append(Factor("structure", None, None, w["structure"], "storico insufficiente"))\n\n    score, f_eff, missing = combine(f)\n    extra = {}\n    if la is not None:\n        # Livelli tecnici indicativi (NON previsioni): invalidazione = max(supporto, close-2ATR)\n        inval = max(support, last - 2 * la) if support is not None else last - 2 * la\n        extra = {\n            "entry_indicative": round(last, 4),\n            "invalidation": round(inval, 4),\n            "target_prudent": round(last + 2 * la, 4),\n            "target_optimistic": round(last + 4 * la, 4),\n            "atr14": round(la, 4),\n            "risk_reward_prudent": round((2 * la) / max(last - inval, 1e-9), 2),\n        }\n    return ScoreResult(\n        engine="titan_technical", score=score, factors=f_eff,\n        data_quality="missing" if score is None else ("delayed" if not missing else "estimated"),\n        missing=missing, as_of=df.index[-1].date(), model_version=MODEL_VERSION, extra=extra)\n', False), 'app.pipeline': ('', True), 'app.pipeline.performance': ('"""Titan Performance: confronto previsione vs realtà a 30/90/180/365 giorni, senza look-ahead.\nUsa SOLO dati successivi alla data di pubblicazione. Prezzi rettificati = includono dividendi/distribuzioni."""\nfrom __future__ import annotations\nimport pandas as pd\n\nCHECKPOINTS = (30, 90, 180, 365)\n\n\ndef evaluate_outcome(pick: dict, published_on: str, df: pd.DataFrame, days: int, bench: pd.Series | None = None) -> dict | None:\n    start = pd.Timestamp(published_on)\n    end = start + pd.Timedelta(days=days)\n    if df.index[-1] < end:\n        return None  # checkpoint non ancora maturato: nessuna valutazione anticipata\n    w = df[(df.index > start) & (df.index <= end)]\n    if w.empty:\n        return None\n    entry = pick["entry_indicative"]\n    last = float(w["close"].iloc[-1])\n    out = {\n        "days": days, "price": round(last, 4), "total_return": round(last / entry - 1, 4),\n        "hit_target_prudent": bool((w["high"] >= pick["target_prudent"]).any()),\n        "hit_target_optimistic": bool((w["high"] >= pick["target_optimistic"]).any()),\n        "invalidated": bool((w["low"] <= pick["invalidation"]).any()),\n        "gap_vs_prudent_target": round(last / pick["target_prudent"] - 1, 4),\n    }\n    if bench is not None:\n        b = bench[(bench.index >= start) & (bench.index <= end)]\n        if len(b) > 1:\n            br = float(b.iloc[-1] / b.iloc[0] - 1)\n            out.update(bench_return=round(br, 4), excess_return=round(out["total_return"] - br, 4))\n    return out\n\n\ndef summarize(outcomes: list[dict]) -> dict:\n    """Aggregato per rendicontare (es. per strategia/orizzonte): include anche i fallimenti."""\n    if not outcomes:\n        return {"n": 0}\n    s = pd.DataFrame(outcomes)\n    return {"n": len(s), "avg_return": round(float(s.total_return.mean()), 4), "win_rate": round(float((s.total_return > 0).mean()), 3),\n            "target_hit_rate": round(float(s.hit_target_prudent.mean()), 3), "invalidated_rate": round(float(s.invalidated.mean()), 3)}\n', False), 'app.pipeline.radar': ('"""Titan Radar: scansione giornaliera -> classifiche per strategia. Nessun minimo di titoli: se nulla supera\nle soglie, il risultato è vuoto e lo dichiara."""\nfrom __future__ import annotations\nfrom dataclasses import dataclass\nfrom datetime import date\nimport pandas as pd\nfrom .. import explain\nfrom ..engines import technical, quant, risk, analyst, fundamentals, bonds, etf as etfmod\nfrom ..universe.etf_verifier import EtfVerifier\n\nMAX_PICKS = 15   # classifica selettiva: al massimo 15 idee per categoria e strategia\nSTRATEGIES = ("prudente", "bilanciata", "aggressiva")\nMIN_SCORE = {"prudente": 65.0, "bilanciata": 65.0, "aggressiva": 65.0}\nSTOCK_EXTRA_MARGIN = 5.0  # azioni SENZA dati fondamentali: soglia più alta\n\n\n@dataclass\nclass Instrument:\n    asset_class: str            # stock | etf | bond\n    name: str\n    ticker: str\n    exchange: str               # es. XMIL\n    currency: str\n    isin: str | None = None\n    fx_unhedged: bool | None = None\n    sector: str | None = None\n\n\ndef evaluate(inst: Instrument, df: pd.DataFrame, bench: pd.Series | None, strategy: str, fund=None, medians=None, etf_rec=None) -> dict:\n    t = technical.analyze(df, bench, strategy)\n    q = quant.analyze(df["close"], bench, strategy)\n    rk = risk.analyze(df, strategy, inst.fx_unhedged)\n    engines = [t, q, rk]\n    fu = None\n    if inst.asset_class == "stock" and fund is not None:\n        fu = fundamentals.analyze(fund, strategy, medians)\n        engines.append(fu)\n    ee = None\n    if inst.asset_class == "etf" and etf_rec is not None:\n        ee = etfmod.analyze(etf_rec, strategy)\n        engines.append(ee)\n    comp = analyst.combine_engines(engines, inst.asset_class)\n    return {"technical": t, "quant": q, "risk": rk, "fundamentals": fu, "etf": ee, "composite": comp}\n\n\ndef build_radar(universe: list[Instrument], load_prices, bench: pd.Series | None,\n                verifier: EtfVerifier | None, today: date | None = None,\n                load_fundamentals=None, sector_medians: dict | None = None,\n                load_bond=None, risk_free: dict | None = None, load_etf=None) -> dict:\n    today = today or date.today()\n    picks = {s: [] for s in STRATEGIES}\n    analyzed: list[dict] = []\n    excluded: list[dict] = []\n    for inst in universe:\n        if inst.asset_class == "bond":\n            _bond_picks(inst, load_bond, risk_free, picks, excluded, today, analyzed); continue\n        if inst.asset_class == "etf":\n            if verifier is None:\n                excluded.append({"ticker": inst.ticker, "reason": "nessuna lista ufficiale Borsa Italiana caricata"}); continue\n            v = verifier.verify(inst.isin or "", inst.ticker, inst.currency)\n            if not v.ok:\n                excluded.append({"ticker": inst.ticker, "isin": inst.isin, "reason": v.reason}); continue\n        try:\n            df = load_prices(inst)\n        except KeyError as e:\n            excluded.append({"ticker": inst.ticker, "reason": f"dati non disponibili: {e}"}); continue\n        stale_days = (today - df.index[-1].date()).days\n        if stale_days > 5:\n            excluded.append({"ticker": inst.ticker, "reason": f"dati non aggiornati ({stale_days} giorni)"}); continue\n        fund = None\n        if inst.asset_class == "stock" and load_fundamentals:\n            try:\n                fund = load_fundamentals(inst)\n            except KeyError:\n                fund = None\n        rec = load_etf(inst) if (load_etf and inst.asset_class == "etf") else None\n        for s in STRATEGIES:\n            ev = evaluate(inst, df, bench, s, fund, (sector_medians or {}).get(fund.sector) if fund else None,\n                          rec)\n            comp = ev["composite"]\n            if comp["score"] is None:\n                excluded.append({"ticker": inst.ticker, "strategy": s, "reason": "dati insufficienti per un punteggio affidabile"}); continue\n            if ev["risk"].extra.get("excessive"):\n                excluded.append({"ticker": inst.ticker, "strategy": s, "reason": "; ".join(ev["risk"].extra["flags"])}); continue\n            thr = MIN_SCORE[s] + (STOCK_EXTRA_MARGIN if "titan_fundamentals" in comp["missing"] and inst.asset_class == "stock" else 0)\n            if comp["score"] < thr:\n                analyzed.append({"n": inst.name, "t": inst.ticker, "c": inst.asset_class, "s": s, "sc": round(comp["score"]), "note": ""}); continue\n            lv = ev["technical"].extra\n            if not lv:\n                continue\n            e, inv, tp, to = lv["entry_indicative"], lv["invalidation"], lv["target_prudent"], lv["target_optimistic"]\n            pk = ({\n                "name": inst.name, "ticker": inst.ticker, "isin": inst.isin, "exchange": inst.exchange,\n                "asset_class": inst.asset_class, "price": round(float(df[\'close\'].iloc[-1]), 4), "price_date": df.index[-1].date().isoformat(),\n                "price_type": "end-of-day (adjusted)", "score": comp["score"], "strategy": s, "horizon": "3-12m",\n                "entry_indicative": e, "invalidation": inv, "target_prudent": tp, "target_optimistic": to,\n                "upside_prudent_pct": round((tp / e - 1) * 100, 2), "upside_optimistic_pct": round((to / e - 1) * 100, 2),\n                "potential_loss_pct": round((inv / e - 1) * 100, 2),\n                "risk_reward_prudent": lv["risk_reward_prudent"],\n                "scenarios": {\n                    "rialzista": {"target": to, "probability": None},\n                    "neutrale": {"target": e, "probability": None},\n                    "ribassista": {"target": inv, "probability": None}},\n                "probability_note": "nessun modello probabilistico validato: probabilità non fornite",\n                "score_detail": {"engines": comp["breakdown"], "missing_engines": comp["missing"], "data_quality": comp["quality"],\n                                 "technical_factors": [vars(f) for f in ev["technical"].factors],\n                                 "fundamental_factors": [vars(f) for f in ev["fundamentals"].factors] if ev["fundamentals"] else None,\n                                 "etf_factors": [vars(f) for f in ev["etf"].factors] if ev["etf"] else None},\n                "risk_flags": ev["risk"].extra["flags"],\n                "disclaimer": "Analisi informativa, non consulenza personalizzata. Livelli indicativi, rendimenti non garantiti.",\n                "model_versions": {"technical": ev["technical"].model_version, "quant": ev["quant"].model_version,\n                                   "risk": ev["risk"].model_version, "analyst": analyst.MODEL_VERSION,\n                                   "fundamentals": ev["fundamentals"].model_version if ev["fundamentals"] else None},\n            })\n            pk.update(explain.build(inst, ev, rec, df, s))\n            hp = (pk.get("hist") or {}).get("p50")\n            pk["potential"] = round(pk["upside_optimistic_pct"] * (0.5 if hp is not None else 1) + (hp * 0.5 if hp is not None else 0), 1)\n            picks[s].append(pk)\n    for s in STRATEGIES:\n        picks[s].sort(key=lambda p: (p.get("potential") or 0) * p["score"] / 100, reverse=True)\n        kept, count = [], {}\n        for p in picks[s]:\n            count[p["asset_class"]] = count.get(p["asset_class"], 0) + 1\n            if count[p["asset_class"]] <= MAX_PICKS:\n                kept.append(p)\n            else:\n                analyzed.append({"n": p["name"], "t": p["ticker"], "c": p["asset_class"], "s": s, "sc": round(p["score"]), "note": f"oltre le prime {MAX_PICKS} idee della categoria"})\n        picks[s] = kept\n    total = sum(len(v) for v in picks.values())\n    return {"date": today.isoformat(), "picks": picks, "excluded": excluded, "analyzed": analyzed,\n            "message": None if total else "Oggi nessuna opportunità supera le soglie di qualità e rischio."}\n\n\ndef _bond_picks(inst, load_bond, risk_free, picks, excluded, today, analyzed=None):\n    if load_bond is None:\n        excluded.append({"ticker": inst.ticker, "reason": "nessuna fonte dati obbligazioni configurata"}); return\n    try:\n        b = load_bond(inst)\n    except KeyError as e:\n        excluded.append({"ticker": inst.ticker, "reason": f"dati non disponibili: {e}"}); return\n    if b.price_date and (today - b.price_date).days > 5:\n        excluded.append({"ticker": inst.ticker, "reason": f"prezzo non aggiornato ({(today - b.price_date).days} giorni)"}); return\n    for s in STRATEGIES:\n        try:\n            r = bonds.analyze(b, s, (risk_free or {}).get(b.currency))\n        except ValueError as e:\n            excluded.append({"ticker": inst.ticker, "reason": str(e)}); return\n        if r.score is None:\n            excluded.append({"ticker": inst.ticker, "strategy": s, "reason": "dati insufficienti"}); continue\n        if r.extra["excessive"]:\n            excluded.append({"ticker": inst.ticker, "strategy": s, "reason": "; ".join(r.extra["flags"])}); continue\n        if r.score < MIN_SCORE[s]:\n            if analyzed is not None:\n                analyzed.append({"n": inst.name, "t": inst.ticker, "c": "bond", "s": s, "sc": round(r.score), "note": f"rendimento {r.extra[\'ytm\']*100:.2f}% · duration {r.extra[\'mod_duration\']:.1f}"})\n            continue\n        e = b.clean_price; y = r.extra["ytm"]\n        p_inv, p_tp, p_to = (bonds.price_at_yield(b, y + 0.01), bonds.price_at_yield(b, y - 0.005), bonds.price_at_yield(b, y - 0.01))\n        yrs = r.extra["years_to_maturity"]\n        picks[s].append({\n            "name": inst.name, "ticker": inst.ticker, "isin": b.isin, "exchange": inst.exchange, "asset_class": "bond",\n            "price": round(e, 4), "price_date": (b.price_date or today).isoformat(), "price_type": "prezzo tel quel (clean), fonte dati utente",\n            "score": r.score, "strategy": s, "horizon": "1-3y" if yrs <= 3 else "3-5y",\n            "entry_indicative": round(e, 4), "invalidation": round(p_inv, 4), "target_prudent": round(p_tp, 4), "target_optimistic": round(p_to, 4),\n            "upside_prudent_pct": round((p_tp / e - 1) * 100, 2), "upside_optimistic_pct": round((p_to / e - 1) * 100, 2),\n            "potential_loss_pct": round((p_inv / e - 1) * 100, 2),\n            "risk_reward_prudent": round((p_tp - e) / max(e - p_inv, 1e-9), 2),\n            "scenarios": {"rialzista": {"target": round(p_to, 4), "probability": None, "ipotesi": "rendimenti -100 bp"},\n                          "neutrale": {"target": round(e, 4), "probability": None, "ipotesi": "rendimenti invariati"},\n                          "ribassista": {"target": round(p_inv, 4), "probability": None, "ipotesi": "rendimenti +100 bp"}},\n            "probability_note": "scenari di sensibilità ai tassi (prezzo, cedole escluse), non previsioni; probabilità non fornite",\n            "score_detail": {"engines": [{"engine": "titan_bonds", "score": r.score, "weight": 1.0}], "missing_engines": ["titan_macro", "titan_news"],\n                             "data_quality": r.data_quality, "bond_factors": [vars(f) for f in r.factors],\n                             "ytm": r.extra["ytm"], "net_ytm_est": r.extra["net_ytm_est"], "mod_duration": r.extra["mod_duration"],\n                             "coupon_pct": b.coupon_pct, "maturity": b.maturity.isoformat(), "rating": b.rating},\n            "risk_flags": r.extra["flags"],\n            "why": [f"Rendimento a scadenza {r.extra[\'ytm\']*100:.2f}% (netto stimato {r.extra[\'net_ytm_est\']*100:.2f}%).", f"Rating {b.rating or \'n/d\'}.", f"Sensibilità ai tassi contenuta: duration {r.extra[\'mod_duration\']:.1f}." if r.extra["mod_duration"] < 5 else f"Duration {r.extra[\'mod_duration\']:.1f}: il prezzo reagisce ai tassi."],\n            "watch": r.extra["flags"] + ["Se i tassi salgono il prezzo scende; liquidità e spread non disponibili.", "È una stima, non una garanzia."],\n            "potential": round((p_to / e - 1) * 100 + (r.extra["net_ytm_est"] or 0) * 100, 1),\n            "risk_level": "basso" if r.score >= 70 else "medio", "facts": {"tipo": "Obbligazionario", "continente": "n/d", "paese": None, "settore": "Obbligazioni " + ("governative" if b.issuer_type == "govt" else "societarie"), "trade_ccy": b.currency}, "hist": None,\n            "disclaimer": "Analisi informativa, non consulenza personalizzata. Sensibilità ai tassi indicativa, rendimenti non garantiti.",\n            "model_versions": {"bonds": bonds.MODEL_VERSION},\n        })\n', False), 'app.pipeline.repository': ('"""Archivio previsioni append-only con hash di integrità (nessuna modifica retroattiva)."""\nfrom __future__ import annotations\nimport hashlib, json\nfrom typing import Protocol\n\n\ndef content_hash(pick: dict) -> str:\n    return hashlib.sha256(json.dumps(pick, sort_keys=True, default=str).encode()).hexdigest()\n\n\nclass PredictionRepo(Protocol):\n    def save(self, pick: dict, published_on: str) -> str: ...\n\n\nclass InMemoryRepo:\n    def __init__(self):\n        self.rows: list[dict] = []\n\n    def save(self, pick: dict, published_on: str) -> str:\n        h = content_hash(pick)\n        if any(r["hash"] == h and r["published_on"] == published_on for r in self.rows):\n            return h  # idempotente: rieseguire il job non duplica\n        self.rows.append({"hash": h, "published_on": published_on, "pick": json.loads(json.dumps(pick, default=str))})\n        return h\n\n\nclass PostgresRepo:\n    """NON TESTATO senza database: richiede `pip install psycopg[binary]` e la migrazione 002.\n    Le tabelle hanno trigger di immutabilità: gli UPDATE/DELETE falliscono per costruzione."""\n    def __init__(self, dsn: str):\n        import psycopg  # import locale: dipendenza opzionale\n        self.conn = psycopg.connect(dsn, autocommit=True)\n\n    def save(self, pick: dict, published_on: str) -> str:\n        h = content_hash(pick)\n        with self.conn.cursor() as cur:\n            cur.execute("""\n              insert into prediction (instrument_id, strategy, horizon, score, entry_price, invalidation,\n                                      target_prudent, target_optim, scenarios, rationale, risks, model_version, content_hash)\n              select i.id, %(strategy)s, %(horizon)s, %(score)s, %(entry)s, %(inv)s, %(tp)s, %(to)s, %(scen)s::jsonb,\n                     %(why)s, %(risks)s, %(mv)s, %(h)s\n              from instrument i where i.isin = %(isin)s\n              on conflict (content_hash) do nothing""",\n              dict(strategy=pick["strategy"], horizon=pick["horizon"], score=pick["score"], entry=pick["entry_indicative"],\n                   inv=pick["invalidation"], tp=pick["target_prudent"], to=pick["target_optimistic"],\n                   scen=json.dumps(pick["scenarios"]), why=json.dumps(pick["score_detail"]),\n                   risks=pick["risk_flags"] or ["vedi score_detail"], mv=json.dumps(pick["model_versions"]),\n                   h=h, isin=pick["isin"]))\n        return h\n', False), 'app.providers': ('', True), 'app.providers.base': ('"""Interfaccia provider: sostituibile senza toccare motori e API."""\nfrom __future__ import annotations\nfrom abc import ABC, abstractmethod\nimport pandas as pd\n\n\nclass PriceProvider(ABC):\n    code: str\n\n    @abstractmethod\n    def daily(self, ticker: str, exchange: str | None = None) -> pd.DataFrame:\n        """DataFrame indicizzato per data con open/high/low/close/volume."""\n\n\nclass CsvProvider(PriceProvider):\n    """Provider di sviluppo: legge data/<TICKER>.csv (date,open,high,low,close,volume)."""\n    code = "csv"\n\n    def __init__(self, folder: str = "data"):\n        self.folder = folder\n\n    def daily(self, ticker: str, exchange: str | None = None) -> pd.DataFrame:\n        try:\n            return pd.read_csv(f"{self.folder}/{ticker.upper()}.csv", parse_dates=["date"], index_col="date")\n        except FileNotFoundError:\n            raise KeyError(f"dati non disponibili per {ticker}")\n\n\nREGISTRY: dict[str, PriceProvider] = {"csv": CsvProvider()}\n\n\ndef get_provider(code: str = "csv") -> PriceProvider:\n    return REGISTRY[code]\n', False), 'app.providers.eodhd': ('"""Provider EODHD (https://eodhd.com/api). Simbolo = {TICKER}.{CODICE_BORSA}.\nPrezzi RETTIFICATI (dividendi/split) per indicatori corretti; l\'HTTP è iniettabile (testabile senza rete).\nNOTA: i codici borsa vanno verificati con /exchanges-list sul tuo account (Milano: \'MI\')."""\nfrom __future__ import annotations\nimport json, time, urllib.parse, urllib.request, urllib.error\nimport pandas as pd\nfrom .base import PriceProvider\n\nBASE = "https://eodhd.com/api"\nEXCHANGE_MAP = {"XMIL": "MI", "XNAS": "US", "XNYS": "US", "XETR": "XETRA", "XPAR": "PA", "XLON": "LSE", "XSWX": "SW"}\n\n\nclass ProviderError(RuntimeError):\n    pass\n\n\ndef _urllib_get(url: str, timeout: int = 20) -> tuple[int, str]:\n    try:\n        with urllib.request.urlopen(url, timeout=timeout) as r:\n            return r.status, r.read().decode()\n    except urllib.error.HTTPError as e:\n        return e.code, e.read().decode()\n\n\nclass EodhdProvider(PriceProvider):\n    code = "eodhd"\n\n    def __init__(self, api_token: str, http_get=_urllib_get, retries: int = 3, sleep=time.sleep):\n        self.token, self.http_get, self.retries, self.sleep = api_token, http_get, retries, sleep\n\n    def _get(self, path: str, **params):\n        q = urllib.parse.urlencode({**params, "api_token": self.token, "fmt": "json"})\n        url = f"{BASE}/{path}?{q}"\n        for attempt in range(self.retries):\n            status, body = self.http_get(url)\n            if status == 200:\n                return json.loads(body)\n            if status == 404:\n                raise KeyError(f"non trovato: {path}")\n            if status in (429, 500, 502, 503, 504) and attempt < self.retries - 1:\n                self.sleep(2 ** attempt)\n                continue\n            raise ProviderError(f"EODHD {status} su {path}")\n        raise ProviderError("retry esauriti")\n\n    @staticmethod\n    def symbol(ticker: str, exchange: str | None) -> str:\n        if "." in ticker:\n            return ticker\n        return f"{ticker}.{EXCHANGE_MAP.get(exchange or \'XMIL\', exchange)}"\n\n    def daily(self, ticker: str, exchange: str | None = None, start: str | None = None) -> pd.DataFrame:\n        params = {"period": "d"}\n        if start:\n            params["from"] = start\n        rows = self._get(f"eod/{self.symbol(ticker, exchange)}", **params)\n        if not rows:\n            raise KeyError(f"nessun dato per {ticker}")\n        df = pd.DataFrame(rows)\n        df["date"] = pd.to_datetime(df["date"])\n        df = df.set_index("date").sort_index()\n        k = (df["adjusted_close"] / df["close"]).where(df["close"] > 0, 1.0)\n        for col in ("open", "high", "low", "close"):\n            df[col] = df[col] * k\n        return df[["open", "high", "low", "close", "volume"]].astype(float)\n\n    def resolve_isin(self, isin: str) -> list[dict]:\n        """Cerca per ISIN: restituisce le quotazioni (Code, Exchange, Currency, ISIN...) trovate."""\n        res = self._get(f"search/{isin}")\n        return [r for r in res if str(r.get("ISIN", "")).upper() == isin.upper()]\n', False), 'app.providers.yahoo': ('"""Provider Yahoo Finance (endpoint NON ufficiale /v8/finance/chart). Adatto a prototipo/uso personale.\nATTENZIONE: nessun contratto/SLA, può cambiare o bloccare senza preavviso (errori 429), termini d\'uso restrittivi\nper usi commerciali/ridistribuzione. Non fornisce ISIN affidabili né fondamentali di qualità. HTTP iniettabile."""\nfrom __future__ import annotations\nimport json, time, urllib.error, urllib.parse, urllib.request\nimport pandas as pd\nfrom .base import PriceProvider\nfrom .eodhd import ProviderError\n\nSUFFIX = {"XMIL": ".MI", "XETR": ".DE", "XPAR": ".PA", "XLON": ".L", "XSWX": ".SW", "XAMS": ".AS", "XTKS": ".T", "XNAS": "", "XNYS": ""}\n\n\ndef _get(url: str, timeout: int = 20) -> tuple[int, str]:\n    req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0 (compatible; TitanInvest/0.1)"})\n    try:\n        with urllib.request.urlopen(req, timeout=timeout) as r:\n            return r.status, r.read().decode()\n    except urllib.error.HTTPError as e:\n        return e.code, e.read().decode()\n\n\nclass YahooProvider(PriceProvider):\n    code = "yahoo"\n\n    def __init__(self, http_get=_get, retries: int = 3, sleep=time.sleep, throttle: float = 0.4, range_: str = "5y"):\n        self.http_get, self.retries, self.sleep, self.throttle, self.range = http_get, retries, sleep, throttle, range_\n        self.meta: dict = {}   # simbolo -> {\'currency\': ..} letto dalla risposta (valuta di negoziazione reale)\n\n    @staticmethod\n    def symbol(ticker: str, exchange: str | None) -> str:\n        return ticker if ("." in ticker or "^" in ticker or exchange is None) else f"{ticker}{SUFFIX.get(exchange, \'\')}"\n\n    def daily(self, ticker: str, exchange: str | None = None) -> pd.DataFrame:\n        url = f"https://query1.finance.yahoo.com/v8/finance/chart/{urllib.parse.quote(self.symbol(ticker, exchange))}?range={self.range}&interval=1d&events=div%2Csplit"\n        for attempt in range(self.retries):\n            self.sleep(self.throttle)\n            status, body = self.http_get(url)\n            if status == 200:\n                break\n            if status == 404:\n                raise KeyError(f"simbolo non trovato su Yahoo: {ticker}")\n            if status in (429, 500, 502, 503) and attempt < self.retries - 1:\n                self.sleep(2 ** (attempt + 1)); continue\n            raise ProviderError(f"Yahoo {status} per {ticker}")\n        res = (json.loads(body).get("chart") or {}).get("result")\n        if not res:\n            raise KeyError(f"nessun dato per {ticker}")\n        r = res[0]\n        self.meta[ticker] = {"currency": (r.get("meta") or {}).get("currency")}\n        q = r["indicators"]["quote"][0]\n        adj = (r["indicators"].get("adjclose") or [{}])[0].get("adjclose")\n        df = pd.DataFrame({"open": q["open"], "high": q["high"], "low": q["low"], "close": q["close"], "volume": q["volume"]},\n                          index=pd.to_datetime(r["timestamp"], unit="s").normalize())\n        if adj is not None:\n            k = pd.Series(adj, index=df.index) / df["close"]\n            for col in ("open", "high", "low", "close"):\n                df[col] = df[col] * k.where(k.notna(), 1.0)\n        df = df.dropna(subset=["close"])\n        df = df[~df.index.duplicated(keep="last")].sort_index()\n        df["volume"] = df["volume"].fillna(0)\n        if df.empty:\n            raise KeyError(f"nessun dato per {ticker}")\n        return df.astype(float)\n', False), 'app.universe': ('', True), 'app.universe.bi_bonds': ('"""Obbligazioni MOT di Borsa Italiana: lettura della scheda (testo reale: rendimento effettivo lordo/netto, duration modificata,\nprezzo di riferimento, scadenza, cedola) e scoperta degli ISIN dai link alle schede. Parser provato su testo reale della scheda BTP."""\nfrom __future__ import annotations\nimport re\nfrom dataclasses import dataclass\nfrom datetime import date\nfrom ..engines.bonds import BondSnapshot\nfrom .borsa_italiana import _n, _s, to_text\nfrom .ratings import sovereign_rating\n\nURL = "https://www.borsaitaliana.it/borsa/obbligazioni/mot/{section}/scheda/{isin}.html?lang=it"\nLISTINGS = ["https://www.borsaitaliana.it/borsa/obbligazioni/mot/btp/lista.html?lang=it&page={page}"]   # NON verificato su pagina reale\n# ISIN di BTP reali osservati sulle schede ufficiali (base minima se l\'elenco non è leggibile)\nSEEDS = ["IT0004532559", "IT0003934657", "IT0005441883", "IT0005083057", "IT0003535157", "IT0005377152", "IT0004286966", "IT0005217390"]\n_LINK = re.compile(r"/borsa/obbligazioni/mot/([a-z\\-]+)/scheda/([A-Z]{2}[A-Z0-9]{9}\\d)", re.I)\n\n\n@dataclass\nclass BondQuote:\n    isin: str; name: str; issuer: str | None; tipologia: str | None; struttura: str | None; currency: str\n    ytm_gross: float | None; ytm_net: float | None; mod_duration: float | None\n    price_ref: float | None; price_date: date | None; maturity: date | None; coupon_pct: float | None; freq: int\n    volume: float | None; contracts: float | None\n\n\ndef _date(s: str | None):\n    m = re.match(r"(\\d{2})/(\\d{2})/(\\d{2,4})", s or "")\n    if not m:\n        return None\n    y = int(m.group(3)); y = y + 2000 if y < 100 else y\n    try: return date(y, int(m.group(2)), int(m.group(1)))\n    except ValueError: return None\n\n\ndef parse(raw: str) -> BondQuote:\n    t = to_text(raw)\n    per = _s(t, r"(?m:^)Periodicità cedola") or ""\n    freq = 2 if per.lower().startswith("seme") else 1 if per.lower().startswith("ann") else 0\n    name = _s(t, r"(?m:^)Denominazione") or ""\n    cp = _n(t, r"Tasso Cedola Periodale")\n    coupon = cp * freq if (cp is not None and freq) else None\n    if coupon is None:\n        m = re.search(r"(\\d+(?:,\\d+)?)\\s*%", name)\n        coupon = float(m.group(1).replace(",", ".")) if m else None\n    if coupon is None and re.search(r"\\bzc\\b|strip", name, re.I):      # BTP strip / zero coupon: nessuna cedola, rimborso a scadenza\n        coupon, freq = 0.0, 1\n    strutt = _s(t, r"(?m:^)Struttura")\n    if coupon is None and (re.search(r"\\bzc\\b|zero\\s*coupon|strip", name, re.I) or "zero" in (strutt or "").lower()):\n        coupon, freq = 0.0, 1          # titoli senza cedola (strip): nessuna cedola periodica\n    ccy = (_s(t, r"(?m:^)Valuta di Negoziazione/ Liquidazione") or "EUR/EUR").split("/")[0].strip().upper()\n    d = re.search(r"Data di riferimento[ \\t:·|]*(\\d{2}/\\d{2}/\\d{2,4})", t, re.I)\n    return BondQuote(isin=(_s(t, r"(?m:^)Codice Isin") or "").upper(), name=name, issuer=_s(t, r"(?m:^)Emittente"), tipologia=_s(t, r"(?m:^)Tipologia"),\n                     struttura=strutt, currency=ccy, ytm_gross=_n(t, r"Rendimento effettivo a scadenza lordo"),\n                     ytm_net=_n(t, r"Rendimento effettivo a scadenza netto"), mod_duration=_n(t, r"Duration modificata"),\n                     price_ref=_n(t, r"Prezzo di riferimento"), price_date=_date(d.group(1)) if d else None,\n                     maturity=_date(_s(t, r"(?m:^)Scadenza")), coupon_pct=coupon, freq=freq, volume=_n(t, r"Volume totale"), contracts=_n(t, r"Numero Contratti"))\n\n\ndef eligible(q: BondQuote, today: date) -> tuple[bool, str]:\n    if not q.isin or q.price_ref is None or q.maturity is None or q.coupon_pct is None or not q.freq:\n        return False, "dati della scheda incompleti"\n    if "indicizz" in (q.struttura or "").lower() or "inflaz" in (q.struttura or "").lower():\n        return False, "obbligazione indicizzata: non gestita"\n    if q.maturity <= today or (q.price_date and (today - q.price_date).days > 7):\n        return False, "scaduta o prezzo non aggiornato"\n    return True, ""\n\n\ndef to_snapshot(q: BondQuote, today: date) -> BondSnapshot:\n    govt = "stato" in (q.tipologia or "").lower()\n    rating, _ = sovereign_rating(q.issuer, today) if govt else (None, None)\n    b = BondSnapshot(q.isin, q.name, q.currency, q.coupon_pct, q.maturity, q.price_ref, "govt" if govt else "corp", rating, q.freq, q.price_date, q.price_date)\n    b.ytm_override = None if q.ytm_gross is None else q.ytm_gross / 100\n    b.net_override = None if q.ytm_net is None else q.ytm_net / 100\n    b.dur_override = q.mod_duration\n    return b\n\n\ndef discover(http_get, listings=None, max_pages: int = 40):\n    """Restituisce ({isin: sezione}, diagnostica). La sezione (btp, euro-obbligazioni...) serve a costruire l\'URL giusto della scheda."""\n    found, diag = {}, {"pagine": 0, "errori": []}\n    for tpl in listings or LISTINGS:\n        for page in range(1, max_pages + 1):\n            st, body = http_get(tpl.format(page=page))\n            if st != 200:\n                diag["errori"].append(f"HTTP {st}"); break\n            diag["pagine"] += 1\n            new = {m.group(2).upper(): m.group(1).lower() for m in _LINK.finditer(body) if m.group(2).upper() not in found}\n            if not new: break\n            found.update(new)\n    for s_ in SEEDS: found.setdefault(s_, "btp")\n    diag["totale"] = len(found)\n    return found, diag\n', False), 'app.universe.bi_stats': ('"""Statistiche mensili ufficiali ETFplus di Borsa Italiana (PDF): elenco degli ETF quotati con ISIN, ticker, scambi mensili e spread.\nURL: .../etf/statistiche/statistichedettaglio/statistichedettaglio<mese><anno>.pdf. Parser a "flusso di token" (indipendente dagli a capo).\nIl formato numerico è quello inglese del 2026 (virgola = migliaia, punto = decimali). Verificato su righe reali di settembre 2026."""\nfrom __future__ import annotations\nimport io, re, subprocess, sys, urllib.request\nfrom dataclasses import dataclass\nfrom datetime import date\nfrom .etf_verifier import isin_valid\n\nBASE = "https://www.borsaitaliana.it/etf/statistiche/statistichedettaglio/statistichedettaglio{m}{y}.pdf"\nMESI = ["gennaio", "febbraio", "marzo", "aprile", "maggio", "giugno", "luglio", "agosto", "settembre", "ottobre", "novembre", "dicembre"]\n_ISIN = re.compile(r"^[A-Z]{2}[A-Z0-9]{9}\\d$")\n_NUM = re.compile(r"^-?[\\d.,]+$")\n_PCT = re.compile(r"^-?[\\d.,]+%\\*?$")\nJUNK = {"#", "PRIVATE", "MAIN", "INDICATORS", "Reference", "Price", "Monthly", "Turnover", "Name", "JAN", "-", "ETF", "Spread", "Segment", "Alphab."}\n\n\n@dataclass\nclass StatRow:\n    isin: str; ticker: str; name: str; segment: str\n    price_end: float | None; var_pct: float | None\n    trades_month: float | None; turnover_month_m: float | None     # milioni di euro\n    trades_ytd: float | None; turnover_ytd_m: float | None; spread_pct: float | None\n    period: str = ""\n\n\ndef _n(s: str) -> float | None:\n    try: return float(s.replace(",", "").replace("%", "").replace("*", ""))\n    except ValueError: return None\n\n\ndef parse_text(text: str, period: str = "") -> list[StatRow]:\n    toks = text.split()\n    rows, start, i = [], 0, 2\n    while i < len(toks) - 9:\n        t = toks[i]\n        if _ISIN.match(t) and isin_valid(t) and re.fullmatch(r".*ETF[AS]?", toks[i - 2]):\n            nums = toks[i + 1:i + 10]\n            ok = (len(nums) == 9 and all(_NUM.match(x) or x.lower() == "n.a." for x in nums[:2]) and _PCT.match(nums[2])\n                  and _NUM.match(nums[3]) and _NUM.match(nums[4]) and _NUM.match(nums[5]) and _NUM.match(nums[6]) and _PCT.match(nums[7]) is None)\n            # colonne: p0 p1 var% trades turnover trades_ytd turnover_ytd spread%  -> 8 campi\n            nums = toks[i + 1:i + 9]\n            ok = (len(nums) == 8 and _PCT.match(nums[2]) and _PCT.match(nums[7]) and all(_NUM.match(nums[k]) for k in (3, 4, 5, 6)))\n            if ok:\n                seg = re.search(r"ETF[AS]?$", toks[i - 2]).group(0)\n                name_toks = [x for x in toks[start:i - 2] if x not in JUNK or len(x) > 6]\n                pre = re.sub(r"ETF[AS]?$", "", toks[i - 2])\n                if pre: name_toks.append(pre)\n                rows.append(StatRow(t, toks[i - 1], " ".join(name_toks).strip(), seg, _n(nums[1]), _n(nums[2]), _n(nums[3]), _n(nums[4]),\n                                    _n(nums[5]), _n(nums[6]), _n(nums[7]), period))\n                start, i = i + 9, i + 9\n                continue\n        i += 1\n    return rows\n\n\ndef _get_bytes(url: str, timeout: int = 60, retries: int = 4):\n    import time\n    st = 0\n    for i in range(retries):\n        req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0 (compatible; TitanInvest/0.1)"})\n        try:\n            with urllib.request.urlopen(req, timeout=timeout) as r:\n                return r.status, r.read()\n        except urllib.error.HTTPError as e:\n            st = e.code\n            if e.code not in (429, 500, 502, 503, 504):\n                return st, b""\n        except Exception:  # noqa: BLE001\n            st = 0\n        time.sleep(2 ** i * 2)\n    return st, b""\n\n\ndef pdf_text(data: bytes) -> str:\n    try:\n        from pypdf import PdfReader\n    except ImportError:\n        subprocess.check_call([sys.executable, "-m", "pip", "install", "-q", "pypdf"])\n        from pypdf import PdfReader\n    return "\\n".join((p.extract_text() or "") for p in PdfReader(io.BytesIO(data)).pages)\n\n\ndef latest(get_bytes=_get_bytes, today: date | None = None, months_back: int = 4) -> tuple[list[StatRow], dict]:\n    today = today or date.today()\n    y, m = today.year, today.month\n    diag = {"tentativi": []}\n    for k in range(1, months_back + 1):                      # mese precedente, poi più indietro\n        mm = (m - 1 - k) % 12\n        yy = y + (m - 1 - k) // 12\n        url = BASE.format(m=MESI[mm], y=yy)\n        st, data = get_bytes(url)\n        diag["tentativi"].append(f"{MESI[mm]} {yy}: HTTP {st}")\n        if st == 200 and data:\n            try:\n                rows = parse_text(pdf_text(data), f"{MESI[mm]} {yy}")\n            except Exception as e:  # noqa: BLE001\n                diag["tentativi"].append(f"errore lettura PDF: {type(e).__name__}: {e}"); continue\n            diag.update(url=url, righe=len(rows), periodo=f"{MESI[mm]} {yy}")\n            if rows:\n                return rows, diag\n    return [], diag\n', False), 'app.universe.borsa_italiana': ('"""Lettura della scheda ETF di Borsa Italiana (https://www.borsaitaliana.it/borsa/etf/scheda/<ISIN>-ETFP.html?lang=it).\nIl parser lavora sul TESTO visibile (etichetta · valore) ed è provato su testo reale della pagina; la struttura HTML\nreale può cambiare: in tal caso il campo resta None (mai inventato) e il record lo dichiara."""\nfrom __future__ import annotations\nimport html, re, urllib.error, urllib.request\nfrom ..engines.etf import EtfRecord\nfrom .etf_verifier import Verification, isin_valid\n\nURL = "https://www.borsaitaliana.it/borsa/etf/scheda/{isin}-ETFP.html?lang=it"\n\n\ndef to_text(raw: str) -> str:\n    t = re.sub(r"(?is)<(script|style).*?</\\1>", " ", raw)\n    t = re.sub(r"(?i)</(td|th|tr|div|li|p|dt|dd|h\\d|span|strong)>|<br\\s*/?>", "\\n", t)\n    t = html.unescape(re.sub(r"<[^>]+>", " ", t)).replace("\\xa0", " ").replace("**", "")\n    return "\\n".join(re.sub(r"[ \\t]+", " ", l).strip() for l in t.splitlines() if l.strip())\n\n\ndef _num(s: str) -> float:\n    return float(s.replace(".", "").replace(",", ".").replace("+", ""))\n\n\ndef _n(text, label):\n    m = re.search(rf"{label}[\\s:·|]*([+\\-]?\\d[\\d.]*(?:,\\d+)?)", text, re.I)\n    return None if not m else _num(m.group(1))\n\n\ndef _s(text, label):\n    m = re.search(rf"{label}[ \\t:·|]*([^\\n|]*)", text, re.I)\n    if not m:\n        return None\n    v = m.group(1).strip()\n    if not v:                                   # nella pagina reale etichetta e valore possono stare su righe diverse\n        nxt = [l.strip() for l in text[m.end():].split("\\n") if l.strip()][:1]\n        v = nxt[0] if nxt else ""\n    return None if not v or v.upper() in ("N.D.", "-") else v\n\n\ndef parse(raw: str, isin_hint: str | None = None) -> EtfRecord:\n    t = to_text(raw)\n    isin = (_s(t, r"Codice Isin") or isin_hint or "").upper()\n    r = EtfRecord(isin=isin, ticker=_s(t, r"Codice Alfanumerico") or "", mic=_s(t, r"\\bMIC"), fund_ccy=_s(t, r"Valuta di Denominazione"),\n                  benchmark=_s(t, r"(?m:^)Benchmark:?"), issuer=_s(t, r"Emittente"), segment=_s(t, r"Segmento"))\n    r.bi_class, r.bi_area = _s(t, r"(?m:^)Classe"), _s(t, r"Area Benchmark:?")\n    d = _s(t, r"Dividendi")\n    r.distribution = None if not d else ("acc" if d.upper().startswith("CAPITAL") else "dist")\n    r.ter_pct = _n(t, r"Commissioni totali annue")\n    r.volume, r.turnover = _n(t, r"Volume totale"), _n(t, r"Controvalore")\n    r.trades = _n(t, r"Numero Contratti")\n    r.perf_1m, r.perf_6m = _n(t, r"Performance 1 mese"), _n(t, r"Performance 6 mesi")\n    r.perf_ytd, r.perf_1y = _n(t, r"Performance da inizio anno"), _n(t, r"Performance 1 anno")\n    r.high_52w, r.low_52w = _n(t, r"Max Anno"), _n(t, r"Min Anno")\n    m = re.search(r"Prezzo di riferimento[\\s:·|]*([\\d.]+,\\d+)\\s*-\\s*(\\d{2})/(\\d{2})/(\\d{2})", t, re.I)\n    if m:\n        r.last_price, r.last_date = _num(m.group(1)), f"20{m.group(4)}-{m.group(3)}-{m.group(2)}"\n    name = re.search(r"(?m)^#\\s*(.+)$", html.unescape(raw))\n    r.name = name.group(1).strip() if name else ""\n    r.name = r.name or (_s(t, r"Denominazione") or "")\n    if re.search(r"Fase:?\\s*(Continuous|Auction|Call|Trading)", t, re.I):\n        r.turnover = r.volume = r.trades = None\n        r.notes.append("seduta in corso al momento della lettura: scambi parziali ignorati; prezzo e performance riferiti all\'ultima chiusura")\n    r.notes.append("valuta di negoziazione non presente nella scheda: da verificare")\n    return r\n\n\ndef _get(url: str, timeout: int = 25, retries: int = 5) -> tuple[int, str]:\n    """GET con nuovi tentativi: Borsa Italiana risponde 429 (troppe richieste) se si va troppo veloci."""\n    import random, time\n    status, body = 0, ""\n    for i in range(retries):\n        req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0 (compatible; TitanInvest/0.1)"})\n        wait = 0.0\n        try:\n            with urllib.request.urlopen(req, timeout=timeout) as resp:\n                return resp.status, resp.read().decode("utf-8", errors="replace")\n        except urllib.error.HTTPError as e:\n            status, body = e.code, e.read().decode("utf-8", errors="replace")\n            if e.code not in (429, 500, 502, 503, 504):\n                return status, body\n            try: wait = float(e.headers.get("Retry-After", 0))\n            except (TypeError, ValueError): wait = 0.0\n        except Exception:  # noqa: BLE001\n            status, body = 0, ""\n        time.sleep(min(max(wait, 2 ** i * 1.5) + random.random(), 30))\n    return status, body\n\n\nclass BorsaItalianaVerifier:\n    """Verifica un ETF direttamente sul sito di Borsa Italiana: la scheda -ETFP (MIC ETFP) deve esistere e\n    riportare lo stesso ISIN e ticker. Conserva i record letti per il punteggio Titan ETF."""\n\n    def __init__(self, http_get=_get, today: str = ""):\n        self.http_get, self.records, self.today = http_get, {}, today\n\n    def verify(self, isin: str, ticker: str, currency: str = "") -> Verification:\n        isin = (isin or "").strip().upper()\n        if not isin_valid(isin):\n            return Verification(False, "ISIN non valido (formato o cifra di controllo)")\n        status, body = self.http_get(URL.format(isin=isin))\n        if status == 404 or (status == 200 and isin not in body.upper()):\n            return Verification(False, "scheda ETFplus non trovata su Borsa Italiana per questo ISIN")\n        if status != 200:\n            return Verification(False, f"Borsa Italiana non raggiungibile (HTTP {status})")\n        r = parse(body, isin)\n        r.asof, r.sources = self.today, [URL.format(isin=isin)]\n        if r.mic != "ETFP" or r.isin != isin:\n            return Verification(False, "la scheda non risulta ETFplus (MIC ETFP) con questo ISIN")\n        if r.ticker.upper() != ticker.upper():\n            return Verification(False, f"ticker diverso su Borsa Italiana ({r.ticker}), probabile linea o classe differente")\n        r.trade_ccy = currency.upper() or None\n        self.records[isin] = r\n        return Verification(True, "verificato sul sito di Borsa Italiana")\n', False), 'app.universe.discovery': ('"""Scoperta automatica degli ETF quotati su Borsa Italiana: legge le pagine di elenco del sito ed estrae gli ISIN dai link alle schede\n(/borsa/etf/scheda/<ISIN>[-ETFP].html). Indipendente dal layout: qualunque pagina che linki le schede produce ISIN.\nATTENZIONE: gli indirizzi di elenco e la paginazione NON sono stati verificati su pagine reali (rete non disponibile al momento dello sviluppo):\nse la scoperta restituisce 0 ISIN, /v1/status lo segnala. Si possono cambiare con BI_LISTING_URLS (usare {page})."""\nfrom __future__ import annotations\nimport os, re\nfrom .etf_verifier import isin_valid\n\nDEFAULT_LISTINGS: list[str] = []   # gli indirizzi ipotizzati risultavano 404/400: l\'elenco ETF ora viene dalle statistiche ufficiali (bi_stats)\n# ISIN di ETF realmente quotati verificati sulle schede ufficiali il 4/11/2026: base minima se l\'elenco non è leggibile\nSEEDS = ["IE00B4L5Y983", "IE00BK5BQT80"]\n_LINK = re.compile(r"/borsa/etf/(?:scheda|dettaglio)[^\\"\'<>\\s]*?([A-Z]{2}[A-Z0-9]{9}\\d)", re.I)\n\n\ndef extract_isins(html: str) -> list[str]:\n    out, seen = [], set()\n    for m in _LINK.finditer(html):\n        i = m.group(1).upper()\n        if i not in seen and isin_valid(i):\n            seen.add(i); out.append(i)\n    return out\n\n\ndef discover(http_get, listings: list[str] | None = None, max_pages: int = 120) -> tuple[list[str], dict]:\n    listings = listings or [u for u in os.environ.get("BI_LISTING_URLS", "").split(",") if u] or DEFAULT_LISTINGS\n    found, diag = {}, {"pagine_lette": 0, "errori": [], "fonti": {}}\n    for tpl in listings:\n        before = len(found)\n        for page in range(1, max_pages + 1):\n            status, body = http_get(tpl.format(page=page))\n            if status != 200:\n                diag["errori"].append(f"HTTP {status} su {tpl.format(page=page)}"); break\n            diag["pagine_lette"] += 1\n            new = [i for i in extract_isins(body) if i not in found]\n            if not new:\n                break\n            for i in new: found[i] = True\n        diag["fonti"][tpl] = len(found) - before\n    for s in SEEDS: found.setdefault(s, True)\n    diag["totale"] = len(found)\n    return list(found), diag\n', False), 'app.universe.etf_list_import': ('"""Importa la lista ETF scaricata da Borsa Italiana (CSV o Excel) riconoscendo le intestazioni in italiano/inglese.\nProduce un CSV normalizzato (isin,ticker,currency,name) e RIFIUTA righe non valide, riportando cosa ha trovato.\nUso: python -m app.universe.etf_list_import ~/Downloads/lista_etf.xlsx data/borsa_italiana_etf.csv"""\nfrom __future__ import annotations\nimport sys, unicodedata\nimport pandas as pd\nfrom .etf_verifier import isin_valid\n\nALIASES = {\n    "isin": ["isin", "codice isin"],\n    "ticker": ["ticker", "tidm", "codice alfanumerico", "alphanumeric code", "simbolo", "codice negoziazione", "local market tidm"],\n    "currency": ["valuta", "valuta di negoziazione", "currency", "trading currency", "divisa"],\n    "name": ["denominazione", "nome", "name", "strumento", "long name", "descrizione", "instrument"],\n}\n\n\ndef _norm(s: str) -> str:\n    s = unicodedata.normalize("NFKD", str(s)).encode("ascii", "ignore").decode().lower().strip()\n    return " ".join(s.replace("_", " ").replace("-", " ").split())\n\n\ndef _find_header(raw: pd.DataFrame) -> int:\n    """Le esportazioni possono avere righe di titolo prima dell\'intestazione: cerca la riga che contiene \'isin\'."""\n    for i in range(min(len(raw), 30)):\n        if any(_norm(v) in ALIASES["isin"] for v in raw.iloc[i].tolist()):\n            return i\n    raise ValueError("intestazione con colonna ISIN non trovata")\n\n\ndef _read_csv(path: str) -> pd.DataFrame:\n    """CSV con eventuali righe di titolo: trova la riga d\'intestazione e deduce il separatore da quella."""\n    lines = open(path, encoding="utf-8-sig", errors="replace").read().splitlines()\n    idx = next((i for i, l in enumerate(lines[:30]) if "isin" in l.lower()), None)\n    if idx is None:\n        raise ValueError("intestazione con colonna ISIN non trovata")\n    sep = max((";", ",", "\\t", "|"), key=lambda c: lines[idx].count(c))\n    return pd.read_csv(path, sep=sep, skiprows=idx, dtype=str, encoding="utf-8-sig", encoding_errors="replace")\n\n\ndef load(path: str) -> tuple[pd.DataFrame, dict]:\n    if path.lower().endswith((".xlsx", ".xls")):\n        raw = pd.read_excel(path, header=None, dtype=str)\n        h = _find_header(raw)\n        df = raw.iloc[h + 1:].copy(); df.columns = [_norm(c) for c in raw.iloc[h].tolist()]\n    else:\n        df = _read_csv(path); df.columns = [_norm(c) for c in df.columns]\n    col = {}\n    for k, names in ALIASES.items():\n        hit = next((c for c in df.columns if c in names), None)\n        if hit: col[k] = hit\n    missing = [k for k in ("isin", "ticker", "currency") if k not in col]\n    if missing:\n        raise ValueError(f"colonne non riconosciute: {missing}. Intestazioni trovate: {list(df.columns)}")\n    out = pd.DataFrame({"isin": df[col["isin"]].str.strip().str.upper(), "ticker": df[col["ticker"]].str.strip(),\n                        "currency": df[col["currency"]].str.strip().str.upper(),\n                        "name": df[col["name"]].str.strip() if "name" in col else ""}).dropna(subset=["isin", "ticker"])\n    ok = out["isin"].map(isin_valid) & out["currency"].str.fullmatch(r"[A-Z]{3}").fillna(False)\n    rep = {"righe_lette": len(out), "valide": int(ok.sum()), "scartate": int((~ok).sum()), "colonne_usate": col,\n           "scartate_esempi": out[~ok].head(5).to_dict("records")}\n    return out[ok].drop_duplicates(["isin", "ticker", "currency"]), rep\n\n\nif __name__ == "__main__":\n    df, rep = load(sys.argv[1]); df.to_csv(sys.argv[2], index=False)\n    print(rep)\n', False), 'app.universe.etf_verifier': ('"""Verifica ETF su Borsa Italiana. Fonte di verità = lista ufficiale Borsa Italiana (ETFplus) caricata dall\'utente.\nUn ETF è ammesso solo se ISIN + ticker + valuta di negoziazione coincidono con una riga della lista ufficiale.\n(Linee diverse dello stesso ISIN, es. EUR/USD, hanno ticker diversi: non vanno confuse.)"""\nfrom __future__ import annotations\nimport csv, re\nfrom dataclasses import dataclass\nfrom datetime import date\n\nISIN_RE = re.compile(r"^[A-Z]{2}[A-Z0-9]{9}[0-9]$")\n\n\ndef isin_valid(isin: str) -> bool:\n    """Formato + cifra di controllo Luhn."""\n    isin = (isin or "").strip().upper()\n    if not ISIN_RE.match(isin):\n        return False\n    digits = "".join(str(int(ch, 36)) for ch in isin)\n    total = 0\n    for i, d in enumerate(reversed(digits)):\n        n = int(d)\n        if i % 2 == 1:\n            n *= 2\n            n = n - 9 if n > 9 else n\n        total += n\n    return total % 10 == 0\n\n\n@dataclass(frozen=True)\nclass OfficialLine:\n    isin: str\n    ticker: str\n    currency: str\n    name: str = ""\n\n\n@dataclass(frozen=True)\nclass Verification:\n    ok: bool\n    reason: str\n    verified_on: date | None = None\n\n\nclass EtfVerifier:\n    def __init__(self, lines: list[OfficialLine], list_date: date):\n        self.list_date = list_date\n        self._by_key = {(l.isin, l.ticker.upper(), l.currency.upper()): l for l in lines}\n        self._isins = {l.isin for l in lines}\n\n    @classmethod\n    def from_csv(cls, path: str, list_date: date, cols=("isin", "ticker", "currency", "name")):\n        """Colonne configurabili: adatta `cols` al file scaricato da Borsa Italiana."""\n        c_isin, c_tick, c_ccy, c_name = cols\n        with open(path, newline="", encoding="utf-8-sig") as f:\n            lines = [OfficialLine(r[c_isin].strip().upper(), r[c_tick].strip(), r[c_ccy].strip().upper(), r.get(c_name, ""))\n                     for r in csv.DictReader(f) if r.get(c_isin)]\n        return cls(lines, list_date)\n\n    def verify(self, isin: str, ticker: str, currency: str) -> Verification:\n        isin = (isin or "").strip().upper()\n        if not isin_valid(isin):\n            return Verification(False, "ISIN non valido (formato o cifra di controllo)")\n        if isin not in self._isins:\n            return Verification(False, "ISIN assente dalla lista ufficiale Borsa Italiana")\n        if (isin, ticker.upper(), currency.upper()) not in self._by_key:\n            return Verification(False, "ISIN presente ma ticker/valuta non corrispondono a una linea quotata su Borsa Italiana")\n        return Verification(True, "verificato su lista ufficiale", self.list_date)\n', False), 'app.universe.ratings': ('"""Rating sovrani con data e fonte. DATO STATICO DA AGGIORNARE: le agenzie rivedono i giudizi più volte l\'anno\n(es. S&P sull\'Italia il 13/11/2026). Una voce più vecchia di 200 giorni viene ignorata (rating non disponibile)."""\nfrom datetime import date\n\nSOVEREIGN = {  # emittente (come scritto da Borsa Italiana) -> (rating S&P/Fitch, nota, data verifica)\n    "REPUBLIC OF ITALY": ("BBB+", "S&P BBB+ outlook positivo (15/05/2026), Fitch BBB+ stabile (11/09/2026), Moody\'s Baa2 stabile (25/09/2026)", date(2026, 11, 4)),\n}\n\n\ndef sovereign_rating(issuer: str | None, today: date | None = None):\n    r = SOVEREIGN.get((issuer or "").strip().upper())\n    if not r or ((today or date.today()) - r[2]).days > 200:\n        return None, None\n    return r[0], r[1]\n', False), 'app.universe.stocks': ('"""Universo azionario automatico: S&P 500 da CSV pubblico (colonne Symbol, Security, GICS Sector, verificate su dati reali) e altri indici\nda tabelle Wikipedia (parser generico per nome di colonna; NON verificato su pagine reali: gli errori finiscono in /v1/status)."""\nfrom __future__ import annotations\nimport csv, io, re\nfrom dataclasses import dataclass\nfrom html.parser import HTMLParser\n\n\n@dataclass\nclass StockRef:\n    symbol: str      # simbolo Yahoo Finance\n    name: str\n    sector: str | None\n    index: str\n\n\nSOURCES = [\n    {"index": "S&P 500", "kind": "csv", "url": "https://datahub.io/core/s-and-p-500-companies/_r/-/data/constituents.csv", "suffix": ""},\n    {"index": "S&P 500 (Wikipedia)", "kind": "wiki", "url": "https://en.wikipedia.org/wiki/List_of_S%26P_500_companies", "suffix": "", "fallback_for": "S&P 500"},\n    {"index": "Nasdaq-100", "kind": "wiki", "url": "https://en.wikipedia.org/wiki/Nasdaq-100", "suffix": ""},\n    {"index": "FTSE MIB", "kind": "wiki", "url": "https://en.wikipedia.org/wiki/FTSE_MIB", "suffix": ".MI"},\n    {"index": "DAX", "kind": "wiki", "url": "https://en.wikipedia.org/wiki/DAX", "suffix": ".DE"},\n    {"index": "CAC 40", "kind": "wiki", "url": "https://en.wikipedia.org/wiki/CAC_40", "suffix": ".PA"},\n    {"index": "FTSE 100", "kind": "wiki", "url": "https://en.wikipedia.org/wiki/FTSE_100_Index", "suffix": ".L"},\n]\nTICK = ("symbol", "ticker", "ticker symbol", "epic", "tidm", "code")\nNAME = ("security", "company", "name", "constituent")\n\n\ndef yahoo_symbol(raw: str, suffix: str) -> str | None:\n    t = re.sub(r"\\[.*?\\]", "", raw or "").strip().upper().split()[0] if (raw or "").strip() else ""\n    t = t.rstrip(".")\n    if not t or not re.fullmatch(r"[A-Z0-9.\\-]{1,12}", t):\n        return None\n    if suffix:\n        base = t[:-len(suffix)] if t.endswith(suffix) else t\n        return base.replace(".", "-") + suffix        # BT.A -> BT-A.L\n    return t.replace(".", "-")          # BRK.B -> BRK-B (Yahoo)\n\n\ndef parse_csv(text: str, suffix: str = "", index: str = "S&P 500") -> list[StockRef]:\n    out = []\n    for r in csv.DictReader(io.StringIO(text)):\n        sym = yahoo_symbol(r.get("Symbol", ""), suffix)\n        if sym: out.append(StockRef(sym, (r.get("Security") or r.get("Name") or sym).strip(), (r.get("GICS Sector") or r.get("Sector") or "").strip() or None, index))\n    return out\n\n\nclass _Tables(HTMLParser):\n    def __init__(self):\n        super().__init__(); self.tables, self._t, self._r, self._c, self._in = [], None, None, None, False\n    def handle_starttag(self, tag, a):\n        if tag == "table": self._t = []\n        elif tag == "tr" and self._t is not None: self._r = []\n        elif tag in ("td", "th") and self._r is not None: self._c, self._in = [], True\n        elif tag == "sup" and self._in: self._c.append("\\x00")\n    def handle_endtag(self, tag):\n        if tag in ("td", "th") and self._r is not None and self._c is not None:\n            txt = "".join(self._c).split("\\x00")[0]; self._r.append(re.sub(r"\\s+", " ", txt).strip()); self._c, self._in = None, False\n        elif tag == "tr" and self._t is not None and self._r:\n            self._t.append(self._r); self._r = None\n        elif tag == "table" and self._t is not None:\n            self.tables.append(self._t); self._t = None\n    def handle_data(self, d):\n        if self._in and self._c is not None: self._c.append(d)\n\n\ndef parse_wiki(html: str, suffix: str, index: str) -> list[StockRef]:\n    p = _Tables(); p.feed(html)\n    best = []\n    for tb in p.tables:\n        hdr = [h.lower() for h in tb[0]]\n        ti = next((i for i, h in enumerate(hdr) if h in TICK), None)\n        ni = next((i for i, h in enumerate(hdr) if h in NAME), None)\n        if ti is None or ni is None: continue\n        si = next((i for i, h in enumerate(hdr) if "sector" in h or "industry" in h), None)\n        rows = []\n        for r in tb[1:]:\n            if len(r) <= max(ti, ni): continue\n            sym = yahoo_symbol(r[ti], suffix)\n            if sym: rows.append(StockRef(sym, r[ni], (r[si] if si is not None and si < len(r) else None) or None, index))\n        if len(rows) > len(best): best = rows\n    return best\n\n\ndef discover(http_get, sources=None) -> tuple[list[StockRef], dict]:\n    out, seen, diag = [], set(), {}\n    ok_idx = set()\n    for s in sources or SOURCES:\n        if s.get("fallback_for") in ok_idx:\n            continue\n        try:\n            st, body = http_get(s["url"])\n            if st != 200:\n                diag[s["index"]] = f"HTTP {st}"; continue\n            rows = parse_csv(body, s["suffix"], s["index"]) if s["kind"] == "csv" else parse_wiki(body, s["suffix"], s["index"])\n        except Exception as e:  # noqa: BLE001\n            diag[s["index"]] = f"{type(e).__name__}: {e}"; continue\n        diag[s["index"]] = len(rows)\n        if rows: ok_idx.add(s["index"])\n        for r in rows:\n            if r.symbol not in seen: seen.add(r.symbol); out.append(r)\n    return out, diag\n', False)}
